import{N as e,P as t,x as n}from"./-Cq37sgm.js";var r=[`en`,`fr`,`tl`,`pa`,`zh-Hans`,`zh-Hant`],i={en:{native:`English`,english:`English`,htmlLang:`en`},fr:{native:`Français`,english:`French (Canadian)`,htmlLang:`fr-CA`},tl:{native:`Tagalog`,english:`Tagalog`,htmlLang:`tl`},pa:{native:`ਪੰਜਾਬੀ`,english:`Punjabi`,htmlLang:`pa`},"zh-Hans":{native:`简体中文`,english:`Chinese (Simplified)`,htmlLang:`zh-Hans`},"zh-Hant":{native:`繁體中文`,english:`Chinese (Traditional)`,htmlLang:`zh-Hant`}},a=`audit_lang`,o=`lang`;function s(e){return!!e&&r.includes(e)}function c(e){let t=e.toLowerCase();if(t.startsWith(`zh`))return t.includes(`hant`)||t.startsWith(`zh-hk`)||t.startsWith(`zh-tw`)||t.startsWith(`zh-mo`)?`zh-Hant`:`zh-Hans`;let n=t.split(`-`)[0];return s(n)?n:null}function l(){let e=new URL(window.location.href).searchParams.get(o);if(s(e))return e;try{let e=localStorage.getItem(a);if(s(e))return e}catch{}let t=navigator.languages??[navigator.language];for(let e of t){let t=c(e);if(t)return t}return`en`}var u=t(`en`);{e(u,l(),!0);let t=new URL(window.location.href);t.searchParams.get(o)!==n(u)&&(t.searchParams.set(o,n(u)),window.history.replaceState({},``,t.toString()))}function d(t){if(!s(t))return;e(u,t,!0);try{localStorage.setItem(a,t)}catch{}let n=new URL(window.location.href);n.searchParams.set(o,t),window.history.replaceState({},``,n.toString())}var f={get current(){return n(u)}},p={en:{selector:{label:`Choose language`},disclaimer:{text:`This site has been translated by AI. Some content may still appear in English while translations are in progress. If you notice errors or would like to help translate this project, please %s.`,link_label:`contact us`},opener:{heading:`Who's this for?`,body:`Us. All of us. Rural, Urban, curious, wonk, journalist, lawyer, academic, politician — all of us. Because it impacts all of us. Whether or not you like the party in power, what the split commission produced has never been done before. And it's given us the opportunity to peer inside the machine in ways we never could before. Now we can establish a baseline — a series of tests, and everything that comes after can be graded on it. Let me show you what I found.`},verdict:{q1:{heading:`Is the proposed map a gerrymander?`,body:`"Gerrymander" is not a term Canadian courts use. But if it were — in the everyday sense most people mean by it — the evidence in this audit would reasonably support calling the <em>minority proposal</em>, if enacted, a heavily gerrymandered map. Every structural test this audit runs flags the <em>minority proposal</em>; none flag the alternative (the <em>majority proposal</em>).`,footnote:`The "majority" and "minority" names come from a 3–2 split among the Electoral Boundaries Commission (chaired by Justice Miller), which produced two competing proposals rather than a single recommendation. A separate MLA committee chaired by Brandon Lunty — a Premier-appointed MLA — is now choosing between them before the November 2026 deadline.`},q2:{heading:`What does "gerrymander" mean in Canadian law?`,body:`It doesn't. The Canadian test is different: whether the boundaries give voters <em>effective representation</em> under section 3 of the Charter. The minority proposal raises serious questions under that test; only a judge can answer them definitively, and no one has asked one yet.`},q3:{heading:`What does it mean for Albertans?`,body:`At a 50/50 provincial vote, the audit's measurements place the minority proposal at a structural extreme — fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. That imbalance matters because at 58 of 87 seats — a two-thirds supermajority — the governing party unlocks extraordinary procedural powers: it can waive standard notice periods and push public bills through multiple legislative stages in a single day, bypassing deliberation checks that normally constrain it. Whether the minority proposal's tilt is large enough to push one party past that 58-seat threshold at vote shares <em>other</em> than 50/50 is a question this audit has not yet tested. Whether the tradeoff itself is acceptable is a question for Albertans, not for this audit.`},cta_law:`Read the legal context →`,cta_methods:`See how we tested →`},head:{title:`Alberta Electoral Boundary Audit`,meta_description:`Statistical audit of Alberta's 2026 electoral boundary commission — 1,010,000 neutral maps, official Elections Alberta shapefiles, pre-registered tests.`},nav:{home_aria:`Back to top`,theme_aria:`Toggle dark/light mode`,theme_title:`Toggle dark mode`,verdict:`Verdict`,why:`Why?`,map:`Map`,split:`The Split`,litmus:`Litmus`,crack_pack:`Crack & Pack`,for_you:`For You`,impact:`Impact`,history:`History`,canada:`Canada`,gerrymanders:`Gerrymanders`,november:`November`,invisible:`Invisible`,retractions:`Retractions`,references:`References`,resources:`Resources`},hero:{h1:`Alberta Electoral Boundary Audit`,subtitle:`Alberta's commission produced two riding maps in 2026. This audit compared them — using the same tests, applied equally to both — to ask whether they treat voters the same way.`,badge:`Official Elections Alberta maps — Published May 2026`,cover_note_1:`This map is the best way in. Click it to zoom and explore. The buttons at the top switch between the minority map, the majority map, and the 2019 enacted boundaries — or layer all three to see exactly where they diverge. <strong>Detail</strong> colours each polling area by how people voted in 2023; <strong>Trend</strong> adds partisan shading by district (blue UCP, orange NDP); <strong>Lines</strong> toggles boundaries on and off. <strong>Find</strong> jumps to any riding by name.`,cover_note_2:`Try locking the viewport and flipping between maps — watch a boundary shift while the voters underneath stay still. That's the whole question in one gesture.`,cover_note_3:`When you're done exploring, scroll down for the summary. For the full technical analysis, see the Resources section. All data is official Elections Alberta shapefiles and other government and open-source records.`,image_alt:`Alberta electoral district maps — minority commission proposal, coloured by 2023 vote`,map_hint:`Click to explore interactively`,btn_title:`Click to open interactive map`,btn_aria:`Open interactive map`},boundary:{heading:`What this audit can and can't tell you`,can_1:`Fewer than 1 in 14.5 million randomly generated comparison maps produced patterns as extreme as the minority proposal on all four statistical measures combined.`,can_2:`The minority proposal fails 5 of 5 pre-registered structural tests. The majority proposal fails 0 of 5.`,can_3:`These results are consistent with maps that produce strong partisan effects, and inconsistent with what the random comparison set produces.`,cant_1:`The audit does <strong>not</strong> establish that any commissioner intended the partisan effects it measures. Boundary geometry cannot reveal intent.`,cant_2:`The audit does <strong>not</strong> predict what the Lunty committee will choose, what the November 2026 vote will be, or how Albertans will react.`,cant_3:`The audit does <strong>not</strong> predict how a court would rule if a Charter challenge were brought against either proposal.`,cant_4:`The audit does <strong>not</strong> tell any individual voter what position to take or what to do with this information. That's yours to decide.`},section1:{heading:`What is redistricting and why should you care?`,p1:`Every voter in Alberta lives in an <em>electoral district</em> — a slice of the province that elects one person to the legislature. There are 87 districts. Each district elects one MLA. When you cast a ballot in a provincial election, you are choosing the MLA for the district you live in. That is the entire connection most Albertans have to the legislature: one MLA, one district, one vote.`,p2:`Those district lines are not permanent. People move, neighbourhoods grow, rural areas thin out, cities sprawl. Every eight to ten years, Alberta is supposed to redraw the lines so each district is roughly the right size and reflects the way Albertans actually live now. The body that does the redrawing is the <em>Electoral Boundaries Commission</em> — an independent commission with judges, lawyers, and public members, not politicians.`,p3:`That is the standard process. This time, the standard process produced something unusual. The commission's five members split 3–2 on what the map should look like, and rather than settling on one recommendation they produced two: a <em>majority proposal</em> (backed by three commissioners) and a <em>minority proposal</em> (backed by two). Both are sitting on the table. A separate committee of MLAs chaired by Brandon Lunty — appointed by the Premier for this specific decision — is choosing between them. The legislature must approve whichever one survives that committee before November 2026.`,p4:`Why it matters to you: the lines decide who your MLA is. They decide which neighbourhoods, towns, and concerns get represented together. If your city is split across four MLAs instead of one, no single representative is accountable for the city as a whole. If your community of interest — a small town, a rural region, a downtown core — is divided between districts, your voice on provincial decisions is diluted. The map also shapes which party can form a government, and at what margins. The audit's specific finding (that the minority proposal sits at a structural extreme) is the reason you are reading this site, but the broader question is older and applies to every redistricting cycle: do the lines reflect the way Albertans live, or do they shape the politics that follow?`,p5:`The rest of this page walks through what the two proposed maps actually do.`,key_terms_lead:`Key terms in this section — click to read:`},section5:{heading:`What this means for you and your community`,intro_p1:`Set aside, for a moment, the question of which party gains or loses seats. Politicians and parties tend to frame this as a fight over power concentration in the legislature, and at that scale it is. But power concentration in the legislature is not where you experience these maps. You experience them through three concrete questions about your own district:`,intro_q1:`Where does your MLA live?`,intro_q2:`Are they invested in your community?`,intro_q3:`Will the demands of the head dominate the demands of the tails?`,intro_p2:`Every other framing — partisan advantage, supermajority threshold, statistical extreme — eventually points back to those three. The five rungs below walk through how each proposed map answers them, at five scales.`,you_h:`You.`,you_p:`Your electoral district decides who represents you in the legislature. Right now you live in one of 87 districts. Under both proposed maps you may live in a different one — possibly with a different MLA, possibly anchored to different neighbouring communities. If you don't know what district you're in right now, or who your MLA is, you're not alone: most Albertans couldn't name their MLA. But the boundary lines are not abstract. They decide whose phone number is on your local representative's office wall, whose neighbourhood petition gets your name attached to it, whose concerns your MLA hears about first. The postal-code lookup on this site shows which district you sit in under each proposal. If your district changes, your representative changes — and your representative's relationship to your community changes with it.`,community_h:`Your community.`,community_p:`Communities are not abstract either. A high school's catchment area, a chamber of commerce, a faith community, a neighbourhood association — these are real groupings of people with shared local concerns. When a boundary line cuts through them, no single MLA is responsible for the whole. Take Airdrie under the minority proposal: a city of about 74,000 people sliced into four electoral districts, each anchored to a different rural hinterland. No single representative is accountable for Airdrie as a city. The same dynamic plays out anywhere a town, neighbourhood, or recognised community of interest is split — the bigger the split, the weaker the representation. The audit measures <em>municipal anchoring</em> (what fraction of each district's perimeter follows existing municipal lines), and the minority proposal scores notably lower than the majority on that test.`,municipality_h:`Your municipality.`,municipality_p:`When a city is fractured across many representatives, its ability to bargain on provincial decisions weakens. A council asking for transit funding, a school board negotiating a new school, a mayor lobbying for highway extensions — each of those goes better when the city can point to a few MLAs who owe accountability to the city as a whole. The minority proposal splits Calgary's northwest quadrant across multiple districts whose vote-share patterns suggest <em>packing</em> (concentrating one party's voters into a few high-margin seats) on top of <em>cracking</em> (splitting the other party's voters across many low-margin seats). Whether the pattern is intentional is a question the audit cannot answer — boundary geometry doesn't reveal intent. What it can say is that the four statistical measures flag the same districts that the structural tests flag, and that the alternative proposal does not produce the same fingerprint.`,region_h:`Your region.`,region_p1:`If you live outside Alberta's cities you have probably noticed that political conversations about boundaries always seem to centre the cities. That's a fair complaint, so let's be direct about what this audit does and does not say about rural Alberta.`,region_p2:`What it does <strong>not</strong> say: that rural Alberta has too many seats. The EBCA allows district populations to vary by up to 25% so that one rural MLA isn't representing a geography the size of southern France. Canadian courts treat that variance as legitimate. Both proposed maps preserve it. Nothing in this audit changes that.`,region_p3:`What it <strong>does</strong> say: in several places on the minority proposal, rural communities are being attached as the <em>tail</em> of a district whose population centre sits in a city. Look at how the minority proposal handles Airdrie — a city of about 74,000 sliced into four districts, each one extended out into a different stretch of rural countryside. The population centre of each new district is the urban slice, not the rural tail. An MLA elected from that kind of district is most likely to live, campaign, and prioritise where the votes are — which means rural communities formerly represented by a dedicated rural MLA become the back half of an urban-led seat. That pattern repeats on the minority proposal in ways it does not on the majority proposal.`,region_p4:`The audit doesn't propose taking seats away from rural Alberta. It asks whether the lines respect the rural communities those seats are meant to represent, or whether rural geography is being used as ballast to absorb urban votes into districts whose centre is somewhere else. If you live in one of those rural tails, the question of which map gets enacted decides whether your MLA represents the rural community you actually live in, or an urban district whose lines happen to include your land.`,province_h:`Your province.`,province_p:`The legislature is what you get when you sum every district's answers to the three questions above. If most districts are anchored to communities whose MLAs actually live in them, the legislature represents those communities. If most districts have rural tails attached to urban heads, the legislature represents the heads — and the tails get whatever attention is left over. The partisan question — which party wins a majority — is downstream of that. The supermajority question — whether one party crosses 58 of 87 seats and unlocks procedural shortcuts like waiving notice periods or accelerating bills through multiple stages in a single day — is downstream of <em>that</em>. At a hypothetical 50/50 provincial split, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. Whether that imbalance pushes a party past 58 seats at the vote shares Albertans actually deliver is a question this audit has not yet directly tested; the verdict at the top of this page is honest about the gap. Whether the answer to any of these questions matters enough to act on is, again, a question for you.`},section6:{heading:`A short history of gerrymandering`,p1:`The word comes from 1812. Massachusetts governor Elbridge Gerry signed off on a state-senate map whose districts were so contorted to favour his party that a Boston cartoonist drew one of them as a salamander — wings, claws, a forked tongue. The cartoonist's pun, <em>Gerry-mander</em>, stuck. The shape stuck too: two centuries later, the word still means drawing electoral lines to engineer a partisan outcome.`,p2:`The term endures because the problem endures. Anywhere voters choose representatives from geographic districts, someone has to draw the lines, and the lines can be drawn many ways. Different countries have arrived at different answers about who should do the drawing and what should constrain them.`,p3:`<strong>The United States</strong> treats partisan gerrymandering as a problem the federal courts mostly cannot fix. In <em>Rucho v. Common Cause</em> (2019), the U.S. Supreme Court ruled that partisan gerrymanders are "political questions" outside its jurisdiction. Some states (California, Michigan) have responded by creating independent citizen commissions to draw their own lines; others (Texas, North Carolina) have continued to draw openly partisan maps and defended them on the basis that <em>Rucho</em> permits it.`,p4:`<strong>The United Kingdom</strong> uses four permanent Boundary Commissions — one each for England, Scotland, Wales, and Northern Ireland — staffed by judges and senior civil servants. They redraw lines roughly every eight years against fixed rules (population equality, geographic coherence, respect for local government boundaries). Parliament can in theory reject the commissions' recommendations, but in practice virtually never does; the convention is that the commissions' judgment stands.`,p5:`<strong>Australia</strong> delegates the work to the Australian Electoral Commission, a federal independent agency with full authority over both election administration and boundaries. Redistributions happen automatically when a state's seat count changes or seven years pass since the last one. The commissioners' decisions are reviewable on procedural grounds but not on partisan ones. Like the U.K., the result is that gerrymandering as Americans know it is virtually unheard of.`,p6:`These three cases bracket the spectrum: courts staying out (U.S.), independent commissions with strong parliamentary deference (U.K.), and a permanent independent agency with full authority (Australia). Canada sits somewhere different again — which is what the next section takes up.`},glossary:{more_link:`Learn more →`,"electoral-district":{term:`Electoral district (ED)`,definition:`The geographic area that elects one member to the provincial legislature. Often shortened to "ED" after first use. Each ED has one MLA. (The word "riding" usually refers to federal districts; in the provincial context the proper term is electoral district.)`},riding:{term:`Riding`,definition:`In Canadian usage, this most often refers to a federal electoral district. The Alberta provincial equivalent is called an "electoral district" (ED). The audit uses the provincial term throughout.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly — the person elected from one electoral district to represent it in the Alberta legislature.`},ucp:{term:`UCP`,definition:`United Conservative Party — Alberta's current governing provincial party. Formed in 2017 from the merger of the Progressive Conservatives and the Wildrose Party; has held government since 2019.`},ndp:{term:`NDP`,definition:`New Democratic Party (Alberta NDP) — Alberta's current official opposition. The Alberta NDP held government from 2015 to 2019.`},gerrymander:{term:`Gerrymander`,definition:`A map drawn so that one political party wins more seats than its share of the vote would suggest. The word comes from an 1812 Massachusetts district shaped like a salamander. It is not a legal term in Canada, but the concept is widely studied.`},cracking:{term:`Cracking`,definition:`A gerrymandering technique that splits a voting bloc across many districts so it never reaches a majority in any single one. For example, dividing a city across four ridings so its voters are outnumbered in each.`},packing:{term:`Packing`,definition:`A gerrymandering technique that concentrates one party's voters into a small number of districts. The party wins those districts overwhelmingly but "wastes" many votes — leaving fewer of its voters available to compete in other districts.`},draining:{term:`Draining`,definition:`A term this audit uses for a follow-on effect of cracking and packing: the wasted votes those techniques produce get pushed into strategically chosen places, altering the political character of nearby electoral districts. It is the audit's own framing rather than an established concept in the redistricting literature — the audit tests for the effect and finds results consistent with it, but treats it as exploratory rather than a settled methodology.`},anchoring:{term:`Anchoring`,definition:`How firmly the proposed boundaries follow existing municipal lines (city limits, town boundaries). A highly anchored map mostly respects those lines; a loosely anchored map departs from them often — especially at politically meaningful spots, which is a structural warning sign.`},"charter-s3":{term:`Section 3 of the Charter`,definition:`The section of the Canadian Charter of Rights and Freedoms that guarantees citizens the right to vote. Canadian courts have interpreted it not as a strict "one person, one vote" rule but as a right to "effective representation."`},"effective-representation":{term:`Effective representation`,definition:`The standard Canadian courts apply when judging electoral boundaries. It means voters should have a meaningful voice — not just numerical equality of riding populations, but also recognition of community ties, geography, and minority representation. The leading statement is from the Supreme Court of Canada's 1991 Saskatchewan Reference.`},ebc:{term:`Electoral Boundaries Commission (EBC)`,definition:`The body that draws Alberta's provincial electoral boundaries under the EBCA. The 2026 commission was chaired by Justice Miller and split 3–2 among its commissioners, producing two competing proposals (the majority and minority proposals) rather than a single recommendation.`},"lunty-committee":{term:`Lunty committee`,definition:`An MLA committee chaired by Brandon Lunty — an MLA appointed by the Premier — that is choosing between the EBC's majority and minority proposals before the November 2026 deadline. The committee is separate from the EBC; the legislature created it for this specific decision and it is not part of the standard EBCA process.`},ebca:{term:`EBCA`,definition:`The Alberta Electoral Boundaries Commission Act — the law that governs how electoral boundaries are drawn in the province. It sets up the commission, the public-hearing process, and the rules for when a new map takes effect.`},fsa:{term:`Forward sortation area (FSA)`,definition:`The first three characters of a Canadian postal code (the letter-digit-letter part). About 270 FSAs cover Alberta. Most fall entirely within a single electoral district.`}},body:{section_link_aria:`Link to section`,the_map:{heading:`1: The Map`,p1:`The cover map is the best single image in this audit. Here is how to read it.`,p2:`Alberta is divided into 4,765 Voting Areas — small geographic zones Elections Alberta uses to count polling-station ballots. Each one is coloured by how people in it actually voted in 2023: orange where NDP votes are concentrated, blue where UCP votes are concentrated. But the colour only becomes dark and saturated where a lot of people live. A Voting Area that covers hundreds of square kilometres of parkland or farmland stays pale — nearly invisible. The map lights up where people are, and fades where they aren't.`,p3:`This is very different from the Alberta you see on election night. Most election maps colour entire ridings solid blue or orange based on who won. Rural ridings are geographically large and the UCP wins most of them, so election-night Alberta looks like a wall of blue with small orange pockets in Edmonton and Calgary. The cover map uses the same votes and the same geography — but shows them weighted by where people actually live. What appears is a province where most of the population is concentrated in a dense arc of cities, and those cities vote very differently from the rural map that normally represents them.`,p4:`The boundary lines drawn over the colour are the minority commission's 89 proposed electoral districts — the map this audit ends up critiquing. The audit's work is to ask what those lines do to the people underneath them.`,p5:`For me personally, this was the image that made the stakes clear. A province that looks like it votes one way on a standard map is actually a province where most of the people live in areas that vote the other way. Once you can see the population underneath the boundary choices, those choices stop looking random.`},structural_results:{heading:`Structural audit results — before any statistics:`,body:`The majority map crosses <strong>zero of five</strong> pre-registered structural thresholds. The minority map crosses <strong>all five</strong>. These are geometric measurements — population spread, <abbr title="how closely a district's borders follow pre-existing city and municipal limits, rather than cutting through them">municipal anchoring</abbr>, Airdrie split count, NW Calgary population excess, and chair-flagged boundary anomalies — that require no election data and no statistical sampler. The next section tests both maps against 1,010,000 computer-generated neutral maps and reaches the same conclusion through a completely different instrument.`},november:{heading:`7: What Happens in November`,context_label:`CONTEXT`,context_body:` — This section describes the process that replaced the commission and the legal framework that applies to it. It is not part of the statistical findings. The findings are in §3–§6 above.`,intro:`Neither commission map is in force. The government set both aside in April 2026 and referred redistricting to a Special Select Committee of five MLAs — three UCP, two NDP — chaired by Brandon Lunty (UCP, Leduc-Beaumont). The committee itself does not draw the map; it oversees a separate advisory panel of five appointees (government-appointed chair, two UCP nominees, two NDP nominees) tasked with producing a 91-seat boundary proposal. The committee must deliver its report to the Legislature by November 2, 2026. Unlike the original commission, neither the committee nor the advisory panel is required to hold public hearings; the panel draws on submissions the original commission gathered. The all-party committee sought a retired or sitting judge to chair the advisory panel; Alberta's acting chief justice declined to nominate one. When the committee's map is released, this audit will apply the same methodology to evaluate it.`,h_anomalous:`Why the Committee Is Anomalous`,anomalous_p1:`Canadian redistricting practice has, since the 1960s, settled on a single model: an independent commission, insulated from government direction, produces boundary recommendations; the legislature may debate them but cannot easily override them without a formal legislative vote. Alberta's statutory process under the <em>Electoral Boundaries Commission Act</em> follows this template — but with one structural difference from most provinces: Alberta's commission report has no automatic legal effect. Under the Act, a separate Electoral Districts Act must be passed by the legislature to give any commission map force of law. That means the government of the day controls not only whether the commission map is debated, but whether it ever becomes law at all. Other Canadian jurisdictions take the opposite default: the commission's recommendations take effect unless the legislature affirmatively votes to override them.`,anomalous_p2:`What the government did in April 2026 has no recorded precedent in post-Confederation redistricting: it allowed a completed, published commission process to conclude — both majority and minority reports filed — and then referred the redistricting task to a five-member committee of MLAs whose majority (three of five) is held by the governing party, without bringing either commission report to a vote. The Lunty committee is not a commission. It has no statutory independence from the government's legislative direction. Its three-member UCP majority mirrors the government's control of the legislature. No other Canadian province has transferred redistricting authority, mid-cycle, to a government-controlled legislative committee after an independent commission had completed its work.`,h_framework:`The Constitutional Framework`,framework_p1:`Section 3 of the <em>Charter of Rights and Freedoms</em> — "Every citizen of Canada has the right to vote in an election of members of the House of Commons or of a legislative assembly" — has been interpreted by the Supreme Court of Canada to guarantee not merely the act of casting a ballot but <em>effective representation</em>. The leading authority is <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, in which McLachlin J. (as she then was) wrote for the majority that the purpose of s.3 "is not equality of voting power per se, but the right to effective representation." Population parity is the primary consideration; departures are permitted when justified by community of interest, geography, history, or minority-representation objectives.`,framework_p2:`The Saskatchewan framework does not categorically prohibit partisan considerations in redistricting. What it establishes is that boundary maps must, on the whole, provide effective representation to voters — and that systematic impairment of one identifiable group's ability to elect proportionate representation is the pattern that s.3 challenges target. The audit's statistical and structural findings — the minority map's position at the 99.99th percentile of 1,010,000 neutral draws, its crossing of all five structural thresholds, the identified communities affected — are the evidentiary record a s.3 applicant would need to assemble. Whether that record meets the constitutional threshold is a legal question this audit does not decide; the audit reports the measurement.`,framework_p3:`The committee's legality as a process is a separate question. Alberta's <em>Electoral Boundaries Commission Act</em> does not expressly prohibit the legislature from constituting a parallel redistricting body, because the Act contemplates that the legislature will enact the final boundaries through ordinary legislation regardless. Whether the committee process, if it produces a map with the structural and statistical profile of the minority proposal, could survive a s.3 Charter challenge turns on whether effective representation is achievable under the resulting boundaries — the same test that would apply to any commission-produced map.`,h_quebec:`The Quebec Contrast`,quebec_p1:`Quebec offers the comparison most relevant to Alberta's situation. Quebec's Commission de la représentation électorale (CRE) is a permanent, independent electoral boundaries body, not an ad hoc commission constituted per redistribution cycle. The CRE operates continuously and cannot be dissolved or bypassed by cabinet action. Under Quebec's <em>Loi électorale</em>, the National Assembly must adopt the CRE's recommendations unless it votes to deviate — and deviations require a two-thirds majority of all members of the Assembly, not a bare legislative majority. The practical effect is that a governing party cannot, acting alone with its own majority, substitute its preferred map for the commission's. Cross-party agreement is constitutionally required to override the independent body's judgment.`,quebec_p2:`Quebec's model emerged partly from lessons about what happens when redistricting is not insulated from partisan control. The contrast with Alberta's current process — where a majority-controlled committee has replaced the commission's work before the legislature has voted on either commission report — illustrates the structural difference between redistricting systems that assume partisan pressure and design against it, versus systems where that pressure has a clearer path to the outcome.`,closing:`The audit will apply the same tests to the Lunty committee's map when it is released. The constitutional and comparative observations above are contextual; the methodology does not change.`}},section7:{heading:`Canada is different — and similar`,p1:`Canada belongs to the same family as the U.S., the U.K., and Australia. We elect single members from geographic districts under first-past-the-post. We redraw the lines periodically — federally after each decennial census, provincially on staggered schedules. We inherited the basic machinery from the same Westminster roots. So far, no surprises.`,p2:`What sets Canada apart is the test the lines have to pass.`,p3:`In American constitutional law, the binding rule is <em>one person, one vote</em> — districts must have populations as nearly equal as practicable, and large departures require strict justification. In Canadian constitutional law, the binding rule is different. Section 3 of the <em>Canadian Charter of Rights and Freedoms</em> guarantees every citizen the right to vote. In <em>Reference re Provincial Electoral Boundaries (Sask.)</em> — the 1991 Saskatchewan Reference, the leading case — the Supreme Court of Canada interpreted that right as a right to <em>effective representation</em>, not a right to mathematical equality of district populations.`,p4:`That distinction matters. Effective representation allows district populations to vary, sometimes substantially, when there are good reasons: vast rural geographies one MLA cannot reasonably serve at standard population density, communities of interest that should be kept together, minority representation mathematical equality would dilute. The Saskatchewan Reference made that flexibility constitutional. The EBCA's 25% population variance — the rule that protects rural Alberta seats — flows directly from it.`,p5:`The catch is that flexibility cuts both ways. If a commission can legitimately depart from population equality for the right reasons, it can also depart from population equality for the wrong ones. Canadian law has no American-style mathematical floor to fall back on. It has the effective-representation test, applied by judges, after the fact, in litigation. Most jurisdictions guard against the wrong reasons with structural protections: federal redistricting commissions are insulated by statute and their recommendations take effect automatically if Parliament does not act on them within a deadline. Quebec uses a permanent independent commission whose work the National Assembly can override only with a two-thirds supermajority. British Columbia operates under a similar default-adopt rule.`,p6:`Alberta is the exception. Under the <em>Electoral Boundaries Commission Act</em>, the commission's report is a recommendation only — the legislature must vote to enact it. That is normally a formality. In the 2026 cycle, the commission split 3–2 and produced two competing proposals; the legislature created a separate MLA committee, chaired by a Premier-appointed MLA, to choose between them. Nothing in Canadian constitutional law required that committee to exist. Nothing requires its choice to follow the commission's process. That is the structural gap this audit is examining.`,p7:`So when Canadian courts say "gerrymander" isn't their legal vocabulary, they are not saying the underlying concept does not apply here. They are saying the test is different — effective representation, not mathematical equality. Whether the minority proposal meets that test is exactly the question this audit has measured the geometry against, and exactly the question only a judge can answer definitively. The <em>Saskatchewan Reference</em> reasoning in full, the contrast with other provinces, the standing question, and the available reform pathways are treated in <a href="#references">the references section below</a>.`}},fr:{selector:{label:`Choisir la langue`},disclaimer:{text:`Ce site a été traduit par IA. Certains contenus peuvent encore apparaître en anglais pendant que les traductions sont en cours. Si vous remarquez des erreurs ou souhaitez aider à traduire ce projet, n'hésitez pas à %s.`,link_label:`nous contacter`},opener:{heading:`À qui s'adresse ce document ?`,body:`À nous. À nous tous. Aux ruraux, aux urbains, aux curieux, aux mordus de politique, aux journalistes, aux avocats, aux universitaires, aux élus — à nous tous. Parce que cela nous touche tous. Que vous aimiez ou non le parti au pouvoir, ce que la commission divisée a produit ne s'était jamais vu auparavant. Et cela nous donne l'occasion d'observer la mécanique de l'intérieur comme nous n'avions jamais pu le faire. Nous pouvons maintenant établir un point de repère — une série de tests, et tout ce qui suivra pourra être évalué à cette aune. Laissez-moi vous montrer ce que j'ai trouvé.`},verdict:{q1:{heading:`La carte proposée est-elle un découpage partisan ?`,body:`« Gerrymander » n'est pas un terme employé par les tribunaux canadiens. Mais s'il l'était — au sens courant que la plupart des gens lui donnent — les éléments de cet audit appuieraient raisonnablement la qualification de la <em>proposition minoritaire</em>, si elle était adoptée, comme une carte fortement remaniée à des fins partisanes. Tous les tests structurels de cet audit signalent la <em>proposition minoritaire</em> ; aucun ne signale l'autre (la <em>proposition majoritaire</em>).`,footnote:`Les noms « majorité » et « minorité » proviennent d'une division 3 contre 2 au sein de la Commission de délimitation électorale (présidée par le juge Miller), qui a produit deux propositions concurrentes plutôt qu'une seule recommandation. Un comité distinct de MLA présidé par Brandon Lunty — un MLA nommé par le Premier ministre — choisit actuellement entre les deux avant la date limite de novembre 2026.`},q2:{heading:`Que signifie « gerrymander » en droit canadien ?`,body:`Rien. Le critère canadien est différent : il s'agit de savoir si les limites garantissent aux électeurs une <em>représentation effective</em> au sens de l'article 3 de la Charte. La proposition minoritaire soulève de sérieuses questions sous ce critère ; seul un juge peut y répondre de façon définitive, et personne n'en a saisi un.`},q3:{heading:`Qu'est-ce que cela signifie pour les Albertains ?`,body:`Lors d'un vote provincial à 50/50, les mesures de l'audit placent la proposition minoritaire dans un extrême structurel — moins de 100 des 1,01 million de cartes neutres de comparaison produisent un déséquilibre de sièges comparable. Ce déséquilibre compte parce qu'à 58 sièges sur 87 — une majorité des deux tiers — le parti au pouvoir débloque des pouvoirs procéduraux exceptionnels : il peut écarter les délais d'avis habituels et faire franchir à un projet de loi public plusieurs étapes législatives en une seule journée, contournant les freins délibératifs qui le contraignent normalement. Savoir si l'inclinaison de la proposition minoritaire est assez forte pour porter un parti au-delà de ce seuil de 58 sièges à des résultats de vote <em>autres</em> que 50/50 est une question que cet audit n'a pas encore examinée. Savoir si le compromis lui-même est acceptable est une question pour les Albertains, et non pour cet audit.`},cta_law:`Lire le contexte juridique →`,cta_methods:`Voir notre méthodologie →`},head:{title:`Audit des limites électorales de l'Alberta`,meta_description:`Audit statistique de la commission albertaine de délimitation électorale de 2026 — 1 010 000 cartes neutres, fichiers officiels d'Elections Alberta, tests pré-enregistrés.`},nav:{home_aria:`Retour en haut`,theme_aria:`Basculer le mode sombre / clair`,theme_title:`Basculer le mode sombre`,verdict:`Verdict`,why:`Pourquoi ?`,map:`Carte`,split:`La Division`,litmus:`Test`,crack_pack:`Diviser et entasser`,for_you:`Pour vous`,impact:`Conséquences`,history:`Histoire`,canada:`Canada`,gerrymanders:`Découpages partisans`,november:`Novembre`,invisible:`L'invisible`,retractions:`Rétractations`,references:`Références`,resources:`Ressources`},hero:{h1:`Audit des limites électorales de l'Alberta`,subtitle:`La commission albertaine a produit deux cartes de circonscriptions en 2026. Cet audit les a comparées — en appliquant les mêmes tests, également aux deux — pour déterminer si elles traitent les électeurs de la même manière.`,badge:`Cartes officielles d'Elections Alberta — publiées en mai 2026`,cover_note_1:`Cette carte est la meilleure porte d'entrée. Cliquez pour zoomer et explorer. Les boutons en haut permettent de basculer entre la proposition minoritaire, la proposition majoritaire et les limites adoptées en 2019 — ou de superposer les trois pour voir exactement où elles divergent. <strong>Detail</strong> colore chaque zone de vote selon le résultat de 2023 ; <strong>Trend</strong> ajoute un ombrage partisan par circonscription (bleu UCP, orange NDP) ; <strong>Lines</strong> active ou désactive les limites. <strong>Find</strong> permet de trouver une circonscription par son nom.`,cover_note_2:`Essayez de verrouiller l'affichage et de passer d'une carte à l'autre — observez une limite se déplacer tandis que les électeurs en dessous restent en place. C'est toute la question en un seul geste.`,cover_note_3:`Quand vous avez fini d'explorer, faites défiler vers le bas pour le résumé. Pour l'analyse technique complète, voir la section Ressources. Toutes les données proviennent des fichiers officiels d'Elections Alberta et d'autres sources gouvernementales et ouvertes.`,image_alt:`Cartes des circonscriptions électorales de l'Alberta — proposition minoritaire de la commission, coloriée selon les votes de 2023`,map_hint:`Cliquer pour explorer de façon interactive`,btn_title:`Cliquer pour ouvrir la carte interactive`,btn_aria:`Ouvrir la carte interactive`},boundary:{heading:`Ce que cet audit peut et ne peut pas vous dire`,can_1:`Moins d'une carte sur 14,5 millions de cartes de comparaison générées aléatoirement a produit des motifs aussi extrêmes que la proposition minoritaire sur l'ensemble des quatre mesures statistiques combinées.`,can_2:`La proposition minoritaire échoue à 5 des 5 tests structurels pré-enregistrés. La proposition majoritaire échoue à 0 sur 5.`,can_3:`Ces résultats sont cohérents avec des cartes qui produisent de forts effets partisans, et incohérents avec ce que produit l'ensemble de comparaison aléatoire.`,cant_1:`L'audit n'établit <strong>pas</strong> qu'un commissaire ait eu l'intention de produire les effets partisans mesurés. La géométrie des limites ne peut révéler l'intention.`,cant_2:`L'audit ne prédit <strong>pas</strong> ce que le comité Lunty choisira, ce que sera le vote de novembre 2026, ni comment les Albertains réagiront.`,cant_3:`L'audit ne prédit <strong>pas</strong> comment un tribunal trancherait si une contestation fondée sur la Charte était intentée contre l'une ou l'autre proposition.`,cant_4:`L'audit ne dit <strong>pas</strong> à un électeur quelle position adopter ni quoi faire de cette information. Cela vous appartient.`},section1:{heading:`Qu'est-ce que la redéfinition des circonscriptions et pourquoi devriez-vous vous y intéresser ?`,p1:`Chaque électeur de l'Alberta vit dans une <em>circonscription électorale</em> — une portion de la province qui élit une personne à l'assemblée législative. Il y a 87 circonscriptions. Chaque circonscription élit un MLA. Quand vous votez à une élection provinciale, vous choisissez le MLA de la circonscription où vous habitez. C'est tout le lien que la plupart des Albertains entretiennent avec l'assemblée législative : un MLA, une circonscription, un vote.`,p2:`Ces limites ne sont pas permanentes. Les gens déménagent, les quartiers grandissent, les régions rurales se vident, les villes s'étendent. Tous les huit à dix ans, l'Alberta est censée redessiner les limites pour que chaque circonscription soit à peu près de la bonne taille et reflète la façon dont les Albertains vivent réellement aujourd'hui. L'organisme qui s'en charge est la <em>Commission de délimitation électorale</em> — une commission indépendante composée de juges, d'avocats et de membres du public, et non de politiciens.`,p3:`C'est le processus standard. Cette fois, le processus standard a produit quelque chose d'inhabituel. Les cinq membres de la commission se sont divisés 3 contre 2 sur ce à quoi la carte devait ressembler et, plutôt que de s'entendre sur une seule recommandation, ils en ont produit deux : une <em>proposition majoritaire</em> (appuyée par trois commissaires) et une <em>proposition minoritaire</em> (appuyée par deux). Les deux sont sur la table. Un comité distinct de MLA présidé par Brandon Lunty — nommé par le Premier ministre pour cette décision précise — est en train de choisir entre les deux. L'assemblée législative doit approuver celle qui survivra à ce comité avant novembre 2026.`,p4:`Pourquoi cela compte pour vous : les limites décident qui est votre MLA. Elles décident quels quartiers, quelles villes et quelles préoccupations sont représentés ensemble. Si votre ville est divisée entre quatre MLA plutôt qu'un seul, aucun représentant unique n'est responsable de la ville dans son ensemble. Si votre communauté d'intérêts — une petite ville, une région rurale, un centre-ville — est divisée entre plusieurs circonscriptions, votre voix sur les décisions provinciales est diluée. La carte façonne aussi quel parti peut former un gouvernement, et à quelle marge. La conclusion précise de cet audit (que la proposition minoritaire se situe dans un extrême structurel) est la raison pour laquelle vous lisez ce site, mais la question plus large est plus ancienne et s'applique à chaque cycle de redécoupage : les limites reflètent-elles la façon dont les Albertains vivent, ou façonnent-elles la politique qui suit ?`,p5:`Le reste de cette page parcourt ce que les deux cartes proposées font réellement.`},section5:{heading:`Ce que cela signifie pour vous et votre communauté`,intro_p1:`Mettons de côté, pour un instant, la question de savoir quel parti gagne ou perd des sièges. Les politiciens et les partis tendent à présenter cela comme une lutte pour la concentration du pouvoir à l'assemblée législative, et à cette échelle c'en est une. Mais la concentration du pouvoir à l'assemblée n'est pas là où vous vivez ces cartes. Vous les vivez à travers trois questions concrètes sur votre propre circonscription :`,intro_q1:`Où vit votre MLA ?`,intro_q2:`Est-il investi dans votre communauté ?`,intro_q3:`Les exigences de la tête vont-elles dominer celles de la queue ?`,intro_p2:`Tout autre cadrage — avantage partisan, seuil de supermajorité, extrême statistique — renvoie en fin de compte à ces trois questions. Les cinq échelons ci-dessous parcourent la manière dont chaque carte proposée y répond, à cinq échelles.`,you_h:`Vous.`,you_p:`Votre circonscription électorale décide qui vous représente à l'assemblée législative. En ce moment, vous vivez dans l'une des 87 circonscriptions. Sous les deux cartes proposées, vous pourriez vous retrouver dans une autre — possiblement avec un autre MLA, possiblement rattaché à des communautés voisines différentes. Si vous ne savez pas dans quelle circonscription vous êtes en ce moment, ou qui est votre MLA, vous n'êtes pas seul : la plupart des Albertains ne sauraient nommer leur MLA. Mais les limites ne sont pas abstraites. Elles décident dont le numéro de téléphone est sur le mur du bureau de votre représentant local, dont la pétition de quartier porte votre nom, dont les préoccupations votre MLA entend en premier. La recherche par code postal sur ce site indique dans quelle circonscription vous vous trouvez sous chaque proposition. Si votre circonscription change, votre représentant change — et la relation de votre représentant avec votre communauté change avec lui.`,community_h:`Votre communauté.`,community_p:`Les communautés ne sont pas abstraites non plus. La zone de fréquentation d'une école secondaire, une chambre de commerce, une communauté religieuse, une association de quartier — ce sont de véritables regroupements de personnes ayant des préoccupations locales communes. Lorsqu'une limite coupe à travers eux, aucun MLA unique n'est responsable de l'ensemble. Prenez Airdrie sous la proposition minoritaire : une ville d'environ 74 000 habitants découpée en quatre circonscriptions, chacune ancrée à un arrière-pays rural différent. Aucun représentant unique n'est responsable d'Airdrie comme ville. La même dynamique se joue partout où une ville, un quartier ou une communauté d'intérêts reconnue est divisée — plus la division est grande, plus la représentation est faible. L'audit mesure l'<em>ancrage municipal</em> (la fraction du périmètre de chaque circonscription qui suit les limites municipales existantes), et la proposition minoritaire obtient un score nettement inférieur à la majoritaire sur ce test.`,municipality_h:`Votre municipalité.`,municipality_p:`Lorsqu'une ville est fragmentée entre de nombreux représentants, sa capacité à négocier sur les décisions provinciales s'affaiblit. Un conseil qui demande du financement pour le transport en commun, une commission scolaire qui négocie une nouvelle école, un maire qui fait pression pour des prolongements d'autoroute — chacun de ces dossiers progresse mieux quand la ville peut s'appuyer sur quelques MLA qui doivent rendre des comptes à la ville dans son ensemble. La proposition minoritaire divise le quadrant nord-ouest de Calgary entre plusieurs circonscriptions dont les schémas de vote suggèrent l'<em>entassement</em> (concentrer les électeurs d'un parti dans quelques sièges à forte marge) en plus du <em>fractionnement</em> (répartir les électeurs de l'autre parti dans plusieurs sièges à faible marge). Savoir si ce schéma est intentionnel est une question à laquelle l'audit ne peut pas répondre — la géométrie des limites ne révèle pas l'intention. Ce qu'il peut dire, c'est que les quatre mesures statistiques signalent les mêmes circonscriptions que les tests structurels signalent, et que la proposition alternative ne produit pas la même empreinte.`,region_h:`Votre région.`,region_p1:`Si vous vivez en dehors des villes de l'Alberta, vous avez probablement remarqué que les conversations politiques sur les limites semblent toujours centrer les villes. C'est une plainte légitime, alors soyons directs sur ce que cet audit dit et ne dit pas sur l'Alberta rurale.`,region_p2:`Ce qu'il ne dit <strong>pas</strong> : que l'Alberta rurale a trop de sièges. La loi sur la délimitation électorale permet aux populations des circonscriptions de varier jusqu'à 25 % afin qu'un MLA rural ne représente pas une géographie de la taille du sud de la France. Les tribunaux canadiens traitent cette variance comme légitime. Les deux cartes proposées la préservent. Rien dans cet audit ne change cela.`,region_p3:`Ce qu'il <strong>dit</strong> : en plusieurs endroits sur la proposition minoritaire, des communautés rurales sont rattachées comme <em>queue</em> d'une circonscription dont le centre de population se trouve dans une ville. Regardez comment la proposition minoritaire traite Airdrie — une ville d'environ 74 000 habitants découpée en quatre circonscriptions, chacune prolongée dans un tronçon différent de la campagne rurale. Le centre de population de chaque nouvelle circonscription est la portion urbaine, pas la queue rurale. Un MLA élu d'une telle circonscription est le plus susceptible d'habiter, de faire campagne et de prioriser là où sont les voix — ce qui signifie que les communautés rurales autrefois représentées par un MLA rural dédié deviennent l'arrière d'un siège dirigé par la ville. Ce schéma se répète sur la proposition minoritaire d'une manière qu'il ne se répète pas sur la proposition majoritaire.`,region_p4:`L'audit ne propose pas de retirer des sièges à l'Alberta rurale. Il demande si les limites respectent les communautés rurales que ces sièges sont censés représenter, ou si la géographie rurale est utilisée comme ballast pour absorber les votes urbains dans des circonscriptions dont le centre est ailleurs. Si vous vivez dans l'une de ces queues rurales, la question de savoir laquelle des cartes sera adoptée décide si votre MLA représente la communauté rurale où vous vivez réellement, ou un district urbain dont les limites incluent simplement votre terrain.`,province_h:`Votre province.`,province_p:`L'assemblée législative est ce que vous obtenez quand vous additionnez les réponses de chaque circonscription aux trois questions ci-dessus. Si la plupart des circonscriptions sont ancrées à des communautés dont les MLA y vivent réellement, l'assemblée représente ces communautés. Si la plupart des circonscriptions ont des queues rurales rattachées à des têtes urbaines, l'assemblée représente les têtes — et les queues obtiennent l'attention qui reste. La question partisane — quel parti remporte la majorité — est en aval de cela. La question de la supermajorité — savoir si un parti franchit 58 des 87 sièges et débloque des raccourcis procéduraux comme la levée des délais d'avis ou l'accélération de projets de loi à travers plusieurs étapes en une seule journée — est en aval de <em>cela</em>. Lors d'un vote provincial hypothétique à 50/50, les mesures de l'audit placent la proposition minoritaire dans un extrême structurel : moins de 100 des 1,01 million de cartes neutres de comparaison produisent un déséquilibre de sièges comparable. Savoir si ce déséquilibre porte un parti au-delà de 58 sièges aux résultats de vote que les Albertains livrent réellement est une question que cet audit n'a pas encore directement examinée ; le verdict en haut de cette page est honnête sur cette lacune. Savoir si la réponse à l'une de ces questions compte assez pour agir est, encore une fois, une question pour vous.`},section6:{heading:`Une brève histoire du découpage partisan`,p1:`Le mot vient de 1812. Le gouverneur du Massachusetts Elbridge Gerry a approuvé une carte sénatoriale dont les circonscriptions étaient si tordues pour favoriser son parti qu'un caricaturiste bostonien en a dessiné une comme une salamandre — ailes, griffes, langue fourchue. Le jeu de mots du caricaturiste, <em>Gerry-mander</em>, est resté. La forme aussi : deux siècles plus tard, le mot signifie toujours tracer des limites électorales pour produire un résultat partisan.`,p2:`Le terme perdure parce que le problème perdure. Partout où les électeurs choisissent des représentants à partir de circonscriptions géographiques, quelqu'un doit tracer les limites, et les limites peuvent être tracées de plusieurs façons. Différents pays sont arrivés à différentes réponses sur qui devrait faire le tracé et ce qui devrait l'encadrer.`,p3:`<strong>Les États-Unis</strong> traitent le découpage partisan comme un problème que les tribunaux fédéraux ne peuvent généralement pas régler. Dans <em>Rucho v. Common Cause</em> (2019), la Cour suprême des États-Unis a statué que les découpages partisans sont des « questions politiques » qui échappent à sa compétence. Certains États (Californie, Michigan) ont réagi en créant des commissions citoyennes indépendantes pour tracer leurs propres limites ; d'autres (Texas, Caroline du Nord) ont continué à tracer des cartes ouvertement partisanes et les ont défendues en s'appuyant sur le fait que <em>Rucho</em> le permet.`,p4:`<strong>Le Royaume-Uni</strong> utilise quatre Commissions permanentes de délimitation — une pour l'Angleterre, l'Écosse, le Pays de Galles et l'Irlande du Nord — composées de juges et de hauts fonctionnaires. Elles retracent les limites tous les huit ans environ selon des règles fixes (égalité de population, cohérence géographique, respect des limites des administrations locales). Le Parlement peut en théorie rejeter les recommandations des commissions, mais dans la pratique ne le fait pratiquement jamais ; la convention veut que le jugement des commissions tienne.`,p5:`<strong>L'Australie</strong> délègue le travail à la Commission électorale australienne, une agence fédérale indépendante avec autorité complète sur l'administration des élections et sur les limites. Les redécoupages ont lieu automatiquement quand le nombre de sièges d'un État change ou que sept ans se sont écoulés depuis le dernier. Les décisions des commissaires peuvent être révisées sur des motifs procéduraux mais pas sur des motifs partisans. Comme au Royaume-Uni, le résultat est que le découpage partisan tel que les Américains le connaissent est pratiquement inconnu.`,p6:`Ces trois cas encadrent le spectre : tribunaux qui restent à l'écart (États-Unis), commissions indépendantes avec forte déférence parlementaire (Royaume-Uni), et agence indépendante permanente avec autorité complète (Australie). Le Canada se situe encore ailleurs — ce que la prochaine section aborde.`},section7:{heading:`Le Canada est différent — et semblable`,p1:`Le Canada appartient à la même famille que les États-Unis, le Royaume-Uni et l'Australie. Nous élisons des membres uniques à partir de circonscriptions géographiques selon le scrutin majoritaire uninominal. Nous retraçons les limites périodiquement — au fédéral après chaque recensement décennal, dans les provinces selon des calendriers échelonnés. Nous avons hérité de la machinerie de base des mêmes racines de Westminster. Jusqu'ici, aucune surprise.`,p2:`Ce qui distingue le Canada, c'est le critère que les limites doivent satisfaire.`,p3:`Dans le droit constitutionnel américain, la règle contraignante est <em>une personne, un vote</em> — les circonscriptions doivent avoir des populations aussi égales que possible, et les écarts importants exigent une justification stricte. Dans le droit constitutionnel canadien, la règle contraignante est différente. L'article 3 de la <em>Charte canadienne des droits et libertés</em> garantit à chaque citoyen le droit de vote. Dans le <em>Renvoi : Circonscriptions électorales provinciales (Sask.)</em> — le Renvoi de la Saskatchewan de 1991, l'arrêt de référence — la Cour suprême du Canada a interprété ce droit comme un droit à une <em>représentation effective</em>, et non comme un droit à l'égalité mathématique des populations de circonscriptions.`,p4:`Cette distinction compte. La représentation effective permet aux populations des circonscriptions de varier, parfois substantiellement, lorsqu'il y a de bonnes raisons : de vastes géographies rurales qu'un MLA ne peut raisonnablement desservir à une densité de population standard, des communautés d'intérêts qui doivent rester groupées, une représentation des minorités que l'égalité mathématique diluerait. Le Renvoi de la Saskatchewan a rendu cette flexibilité constitutionnelle. La variance de population de 25 % de la loi sur la délimitation électorale — la règle qui protège les sièges ruraux de l'Alberta — en découle directement.`,p5:`Le hic, c'est que la flexibilité fonctionne dans les deux sens. Si une commission peut légitimement s'écarter de l'égalité de population pour les bonnes raisons, elle peut aussi s'en écarter pour les mauvaises. Le droit canadien n'a pas de plancher mathématique à l'américaine sur lequel se rabattre. Il a le critère de représentation effective, appliqué par les juges, après coup, en cas de litige. La plupart des juridictions se prémunissent contre les mauvaises raisons avec des protections structurelles : les commissions fédérales de redécoupage sont isolées par la loi et leurs recommandations entrent en vigueur automatiquement si le Parlement n'agit pas dans un délai imparti. Le Québec utilise une commission permanente indépendante dont l'Assemblée nationale ne peut renverser le travail qu'à une majorité des deux tiers. La Colombie-Britannique fonctionne selon une règle d'adoption par défaut similaire.`,p6:`L'Alberta est l'exception. En vertu de la <em>Electoral Boundaries Commission Act</em>, le rapport de la commission n'est qu'une recommandation — l'assemblée législative doit voter pour l'adopter. C'est normalement une formalité. Dans le cycle 2026, la commission s'est divisée 3 contre 2 et a produit deux propositions concurrentes ; l'assemblée a créé un comité distinct de MLA, présidé par un MLA nommé par le Premier ministre, pour choisir entre elles. Rien dans le droit constitutionnel canadien n'exigeait que ce comité existe. Rien n'exige que son choix suive le processus de la commission. C'est la lacune structurelle que cet audit examine.`,p7:`Donc, quand les tribunaux canadiens disent que « découpage partisan » n'est pas leur vocabulaire juridique, ils ne disent pas que le concept sous-jacent ne s'applique pas ici. Ils disent que le critère est différent — représentation effective, et non égalité mathématique. Savoir si la proposition minoritaire répond à ce critère est exactement la question contre laquelle cet audit a mesuré la géométrie, et exactement la question à laquelle seul un juge peut répondre de façon définitive. Le raisonnement complet du <em>Renvoi de la Saskatchewan</em>, le contraste avec d'autres provinces, la question de la qualité pour agir et les voies de réforme disponibles sont traités dans <a href="#references">la section des références ci-dessous</a>.`}},tl:{selector:{label:`Pumili ng wika`},disclaimer:{text:`Isinalin ang site na ito sa pamamagitan ng AI. Maaaring may mga nilalamang nasa Ingles pa habang isinasagawa ang pagsasalin. Kung may mga mali o nais ninyong tumulong sa pagsasalin ng proyektong ito, mangyaring %s.`,link_label:`makipag-ugnayan sa amin`},opener:{heading:`Para kanino ito?`,body:`Para sa atin. Para sa ating lahat. Sa mga taga-bukid, sa mga taga-lungsod, sa mga curious, sa mga mahilig sa pulitika, sa mga mamamahayag, sa mga abugado, sa mga akademiko, sa mga pulitiko — para sa ating lahat. Dahil nakakaapekto ito sa ating lahat. Anuman ang iyong palagay sa partidong nasa poder, ang ginawa ng hating komisyon ay hindi pa nangyari noon. At binigyan tayo nito ng pagkakataong masilip ang loob ng makinarya sa paraang hindi pa natin nagawa. Ngayon ay maaari na tayong magtatag ng isang batayan — isang serye ng mga pagsusulit, at lahat ng susunod ay maaaring sukatin batay dito. Hayaan ninyong ipakita ko sa inyo ang aking natuklasan.`},verdict:{q1:{heading:`Ang iminungkahing mapa ba ay isang gerrymander?`,body:`Ang "gerrymander" ay hindi terminong ginagamit ng mga korte sa Canada. Ngunit kung gagamitin ito — sa pang-araw-araw na kahulugang ibinibigay ng karamihan — ang mga ebidensya sa audit na ito ay makatuwirang sumusuporta sa pagtawag sa <em>panukala ng minorya</em>, kung ito ay magiging batas, bilang isang mapa na malalim na gerrymandered. Lahat ng istrukturang pagsusulit ng audit na ito ay tumutukoy sa <em>panukala ng minorya</em>; wala ni isa ang tumutukoy sa kabilang panukala (ang <em>panukala ng mayorya</em>).`,footnote:`Ang mga pangalang "mayorya" at "minorya" ay galing sa 3–2 na paghahati sa Electoral Boundaries Commission (pinamumunuan ni Justice Miller), na nagprodyus ng dalawang nagtutunggaling panukala sa halip na isang rekomendasyon. Isang hiwalay na komite ng mga MLA na pinamumunuan ni Brandon Lunty — isang MLA na hinirang ng Premier — ang pumipili ngayon sa pagitan ng mga ito bago ang takdang petsa ng Nobyembre 2026.`},q2:{heading:`Ano ang ibig sabihin ng "gerrymander" sa batas ng Canada?`,body:`Wala. Iba ang pagsusuri ng Canada: kung binibigyan ng <em>epektibong representasyon</em> ang mga botante sa ilalim ng seksyon 3 ng Charter. Ang panukala ng minorya ay nagdudulot ng mga seryosong tanong sa ilalim ng pagsusuring iyon; isang hukom lamang ang makakasagot ng tiyak, at walang sinuman pa ang nagtanong sa kanya.`},q3:{heading:`Ano ang ibig sabihin nito para sa mga Albertan?`,body:`Sa isang 50/50 na boto sa probinsya, inilalagay ng mga sukat ng audit ang panukala ng minorya sa isang istrukturang sukdulan — mas mababa sa 100 ng 1.01 milyong neutral na mga mapa ng paghahambing ang nagbibigay ng kaparehong uri ng kawalan ng balanse sa upuan. Mahalaga ang kawalan ng balanseng iyon dahil sa 58 ng 87 upuan — isang dalawang-katlong supermayorya — ang naghaharing partido ay nakakakuha ng pambihirang mga kapangyarihang pamamaraan: maaari nitong tanggalin ang karaniwang mga panahon ng abiso at itulak ang mga panukalang batas sa pamamagitan ng maraming yugto ng pambabatasan sa isang araw lamang, lampas sa mga pagsusuri ng paglalapat na karaniwang nagpipigil sa kanya. Kung ang pagkakahilig ng panukala ng minorya ay sapat na laki upang itulak ang isang partido lampas sa hangganang 58-upuan sa mga sukat ng boto na <em>iba</em> sa 50/50 ay isang tanong na hindi pa sinuri ng audit na ito. Kung katanggap-tanggap ang pagpapalitan mismo ay isang tanong para sa mga Albertan, hindi para sa audit na ito.`},cta_law:`Basahin ang legal na konteksto →`,cta_methods:`Tingnan kung paano namin sinubukan →`},head:{title:`Pag-audit ng Hangganan ng Halalan sa Alberta`,meta_description:`Estadistikong pag-audit ng komisyon ng hangganan ng halalan sa Alberta sa 2026 — 1,010,000 neutral na mga mapa, opisyal na mga shapefile ng Elections Alberta, mga pre-registered na pagsusulit.`},nav:{home_aria:`Bumalik sa itaas`,theme_aria:`Palitan ang madilim / maliwanag na mode`,theme_title:`Palitan ang madilim na mode`,verdict:`Hatol`,why:`Bakit?`,map:`Mapa`,split:`Ang Paghahati`,litmus:`Pagsusulit`,crack_pack:`Crack at Pack`,for_you:`Para Sa Iyo`,impact:`Epekto`,history:`Kasaysayan`,canada:`Canada`,gerrymanders:`Mga Gerrymander`,november:`Nobyembre`,invisible:`Hindi Nakikita`,retractions:`Mga Pagbawi`,references:`Mga Sanggunian`,resources:`Mga Mapagkukunan`},hero:{h1:`Pag-audit ng Hangganan ng Halalan sa Alberta`,subtitle:`Ang komisyon ng Alberta ay nagprodyus ng dalawang mapa ng riding sa 2026. Inihambing ng audit na ito ang mga ito — gamit ang parehong mga pagsusulit, na inilapat nang pantay sa pareho — upang itanong kung pareho nilang itinuturing ang mga botante.`,badge:`Mga opisyal na mapa ng Elections Alberta — Inilathala noong Mayo 2026`,cover_note_1:`Ang mapang ito ang pinakamahusay na paraan upang magsimula. I-click ito upang mag-zoom at galugarin. Ang mga pindutan sa itaas ay nagpapalipat sa pagitan ng mapa ng minorya, mapa ng mayorya, at mga hangganan na nasaad noong 2019 — o ilatag ang lahat ng tatlo upang makita kung saan sila eksaktong nag-iiba. Kinukulayan ng <strong>Detail</strong> ang bawat polling area ayon sa paano bumoto ang mga tao noong 2023; nagdadagdag ang <strong>Trend</strong> ng partisan shading bawat distrito (asul UCP, kahel NDP); ginagawang on/off ng <strong>Lines</strong> ang mga hangganan. Ang <strong>Find</strong> ay lumulukso sa anumang riding ayon sa pangalan.`,cover_note_2:`Subukang i-lock ang viewport at mag-flip sa pagitan ng mga mapa — pagmasdan ang isang hangganan na lumilipat habang ang mga botante sa ilalim ay nananatiling tahimik. Iyon ang buong tanong sa isang galaw.`,cover_note_3:`Kapag tapos ka nang mag-explore, mag-scroll pababa para sa buod. Para sa kumpletong teknikal na pagsusuri, tingnan ang seksyon ng Mga Mapagkukunan. Lahat ng data ay mula sa opisyal na shapefile ng Elections Alberta at iba pang gobyerno at open-source na mga rekord.`,image_alt:`Mga mapa ng distritong pang-eleksyon sa Alberta — panukala ng minorya ng komisyon, kinulayan ayon sa boto noong 2023`,map_hint:`I-click upang galugarin nang interactive`,btn_title:`I-click upang buksan ang interactive na mapa`,btn_aria:`Buksan ang interactive na mapa`},section1:{heading:`Ano ang redistricting at bakit ito ay dapat mahalaga sa iyo?`,p1:`Ang bawat botante sa Alberta ay naninirahan sa isang <em>elektoral na distrito</em> — isang seksyon ng probinsya na pumipili ng isang tao sa lehislatura. May 87 distrito. Ang bawat distrito ay pumipili ng isang MLA. Kapag ikaw ay bumoboto sa isang elektoral na probinsya, pinipili mo ang MLA para sa distrito kung saan ka nakatira. Iyon ang buong koneksyon ng karamihan sa mga Albertan sa lehislatura: isang MLA, isang distrito, isang boto.`,p2:`Ang mga linyang ito ng distrito ay hindi permanente. Lumilipat ang mga tao, lumalago ang mga kapitbahayan, ang mga lugar sa kanayunan ay nagiging manipis, at ang mga lungsod ay lumalawak. Tuwing walo hanggang sampung taon, dapat na muling iguhit ng Alberta ang mga linya upang ang bawat distrito ay nasa tamang sukat at sumasalamin sa kung paano talaga nakatira ang mga Albertan ngayon. Ang katawan na muling gumuhit ay ang <em>Komisyon ng Hangganan ng Halalan</em> — isang independiyenteng komisyon na may mga huwes, abugado, at miyembro ng publiko, hindi mga politiko.`,p3:`Iyon ang karaniwang proseso. Sa pagkakataong ito, ang karaniwang proseso ay nagprodyus ng isang bagay na hindi karaniwan. Ang limang miyembro ng komisyon ay naghati-hati ng 3 sa 2 sa kung anong itsura ng mapa ay dapat, at sa halip na magkasundo sa isang rekomendasyon, sila ay nagprodyus ng dalawa: isang <em>panukala ng mayorya</em> (sinusuportahan ng tatlong komisyonado) at isang <em>panukala ng minorya</em> (sinusuportahan ng dalawa). Ang dalawa ay nakapatong sa mesa. Isang hiwalay na komite ng mga MLA na pinamumunuan ni Brandon Lunty — hinirang ng Premier para sa partikular na desisyong ito — ang pumipili sa pagitan ng mga ito. Ang lehislatura ay dapat aprubahan kung alin ang makakaligtas sa komiteng iyon bago ang Nobyembre 2026.`,p4:`Kung bakit ito mahalaga sa iyo: ang mga linya ay nagdedesisyon kung sino ang iyong MLA. Sila ang nagdedesisyon kung anong mga kapitbahayan, bayan, at alalahanin ang kinakatawan nang magkasama. Kung ang iyong lungsod ay nahahati sa apat na MLA sa halip na isa, walang iisang kinatawan ang may pananagutan para sa lungsod sa kabuuan. Kung ang iyong komunidad ng interes — isang maliit na bayan, isang rural na rehiyon, isang sentro ng lungsod — ay nahahati sa pagitan ng mga distrito, ang iyong boses sa mga desisyon ng probinsya ay nalalabnaw. Hinuhubog din ng mapa kung anong partido ang maaaring magtatag ng gobyerno, at sa anong margin. Ang partikular na natuklasan ng audit (na ang panukala ng minorya ay nasa isang sukdulan ng istraktura) ay ang dahilan kung bakit binabasa mo ang site na ito, ngunit ang mas malawak na tanong ay mas matanda at naaangkop sa bawat redistricting cycle: ang mga linya ba ay sumasalamin sa kung paano nakatira ang mga Albertan, o hinuhubog ba nila ang pulitika na susunod?`,p5:`Ang natitirang bahagi ng pahinang ito ay tumatakbo sa kung ano talaga ang ginagawa ng dalawang iminungkahing mapa.`,key_terms_lead:`Mga pangunahing termino sa seksyong ito — i-click upang basahin:`},boundary:{heading:`Kung ano ang masasabi at hindi masasabi ng audit na ito`,can_1:`Mas mababa sa 1 sa 14.5 milyong random na nilikhang mga mapa ng paghahambing ang nagprodyus ng mga pattern na kasinghirap ng panukala ng minorya sa lahat ng apat na estadistikong sukat na pinagsama.`,can_2:`Ang panukala ng minorya ay bumagsak sa 5 sa 5 pre-registered na istrukturang pagsusulit. Ang panukala ng mayorya ay bumagsak sa 0 sa 5.`,can_3:`Ang mga resultang ito ay tugma sa mga mapa na nagpoprodyus ng malalakas na epektong partisan, at hindi tugma sa kung ano ang prinopodyus ng random na set ng paghahambing.`,cant_1:`Ang audit ay <strong>hindi</strong> nagtatatag na anumang komisyonado ay may intensyon sa mga epektong partisan na sinusukat nito. Hindi maipakikita ng geometriya ng hangganan ang intensyon.`,cant_2:`Ang audit ay <strong>hindi</strong> humuhula kung ano ang pipiliin ng Lunty committee, kung ano ang magiging boto sa Nobyembre 2026, o kung paano magrereaksyon ang mga Albertan.`,cant_3:`Ang audit ay <strong>hindi</strong> humuhula kung paano huhusgahan ng isang korte kung magsasampa ng Charter challenge laban sa alinmang panukala.`,cant_4:`Ang audit ay <strong>hindi</strong> nagsasabi sa anumang indibidwal na botante kung anong posisyon ang dapat kunin o ano ang gagawin sa impormasyong ito. Sa inyo iyon na desisyon.`}},pa:{selector:{label:`ਭਾਸ਼ਾ ਚੁਣੋ`},disclaimer:{text:`ਇਸ ਸਾਈਟ ਦਾ ਅਨੁਵਾਦ AI ਦੁਆਰਾ ਕੀਤਾ ਗਿਆ ਹੈ। ਅਨੁਵਾਦ ਚੱਲ ਰਹੇ ਹੋਣ ਦੌਰਾਨ ਕੁਝ ਸਮੱਗਰੀ ਅਜੇ ਵੀ ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ ਦਿਖਾਈ ਦੇ ਸਕਦੀ ਹੈ। ਜੇ ਤੁਸੀਂ ਗਲਤੀਆਂ ਦੇਖਦੇ ਹੋ ਜਾਂ ਇਸ ਪ੍ਰੋਜੈਕਟ ਦੇ ਅਨੁਵਾਦ ਵਿੱਚ ਮਦਦ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਕਿਰਪਾ ਕਰਕੇ %s।`,link_label:`ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ`},opener:{heading:`ਇਹ ਕਿਸ ਲਈ ਹੈ?`,body:`ਸਾਡੇ ਲਈ। ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ। ਪੇਂਡੂ, ਸ਼ਹਿਰੀ, ਜਿਗਿਆਸੂ, ਸਿਆਸਤ ਦੇ ਸ਼ੁਕੀਨ, ਪੱਤਰਕਾਰ, ਵਕੀਲ, ਵਿਦਵਾਨ, ਚੁਣੇ ਹੋਏ ਨੁਮਾਇੰਦੇ — ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ। ਕਿਉਂਕਿ ਇਹ ਸਾਨੂੰ ਸਾਰਿਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦਾ ਹੈ। ਭਾਵੇਂ ਤੁਸੀਂ ਸੱਤਾਧਾਰੀ ਪਾਰਟੀ ਨੂੰ ਪਸੰਦ ਕਰਦੇ ਹੋ ਜਾਂ ਨਹੀਂ, ਜੋ ਵੰਡੇ ਹੋਏ ਕਮਿਸ਼ਨ ਨੇ ਪੈਦਾ ਕੀਤਾ ਉਹ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ ਹੋਇਆ। ਅਤੇ ਇਸ ਨੇ ਸਾਨੂੰ ਇਸ ਮਸ਼ੀਨ ਦੇ ਅੰਦਰ ਝਾਤੀ ਮਾਰਨ ਦਾ ਮੌਕਾ ਦਿੱਤਾ ਹੈ ਜਿਸ ਤਰ੍ਹਾਂ ਅਸੀਂ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ ਮਾਰ ਸਕੇ। ਹੁਣ ਅਸੀਂ ਇੱਕ ਆਧਾਰ-ਰੇਖਾ ਸਥਾਪਤ ਕਰ ਸਕਦੇ ਹਾਂ — ਪਰੀਖਣਾਂ ਦੀ ਇੱਕ ਲੜੀ, ਅਤੇ ਜੋ ਕੁਝ ਵੀ ਬਾਅਦ ਵਿੱਚ ਆਉਂਦਾ ਹੈ ਉਸਨੂੰ ਇਸ ਦੇ ਆਧਾਰ ਉੱਤੇ ਪਰਖਿਆ ਜਾ ਸਕਦਾ ਹੈ। ਮੈਨੂੰ ਤੁਹਾਨੂੰ ਦਿਖਾਉਣ ਦਿਓ ਕਿ ਮੈਂ ਕੀ ਲੱਭਿਆ ਹੈ।`},verdict:{q1:{heading:`ਕੀ ਪ੍ਰਸਤਾਵਿਤ ਨਕਸ਼ਾ ਇੱਕ ਗੈਰੀਮੈਂਡਰ ਹੈ?`,body:`"ਗੈਰੀਮੈਂਡਰ" ਕੈਨੇਡੀਅਨ ਅਦਾਲਤਾਂ ਦੁਆਰਾ ਵਰਤਿਆ ਜਾਣ ਵਾਲਾ ਸ਼ਬਦ ਨਹੀਂ ਹੈ। ਪਰ ਜੇ ਇਹ ਹੁੰਦਾ — ਜਿਸ ਆਮ ਅਰਥ ਵਿੱਚ ਜ਼ਿਆਦਾਤਰ ਲੋਕ ਇਸਨੂੰ ਸਮਝਦੇ ਹਨ — ਤਾਂ ਇਸ ਆਡਿਟ ਦੇ ਸਬੂਤ ਮੁਨਾਸਬ ਤੌਰ ਤੇ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> ਨੂੰ, ਜੇ ਲਾਗੂ ਕੀਤਾ ਜਾਵੇ, ਇੱਕ ਡੂੰਘੀ ਗੈਰੀਮੈਂਡਰਡ ਨਕਸ਼ੇ ਵਜੋਂ ਕਹਿਣ ਦੀ ਹਮਾਇਤ ਕਰਨਗੇ। ਇਸ ਆਡਿਟ ਦੇ ਹਰ ਸੰਰਚਨਾਤਮਕ ਪਰੀਖਣ ਵਿੱਚ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> ਚਿੰਨ੍ਹਿਤ ਹੁੰਦੀ ਹੈ; ਕੋਈ ਵੀ ਬਦਲ (<em>ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em>) ਨੂੰ ਚਿੰਨ੍ਹਿਤ ਨਹੀਂ ਕਰਦਾ।`,footnote:`"ਬਹੁ-ਗਿਣਤੀ" ਅਤੇ "ਘੱਟ-ਗਿਣਤੀ" ਨਾਂ ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ (ਜਸਟਿਸ ਮਿਲਰ ਦੀ ਪ੍ਰਧਾਨਗੀ ਅਧੀਨ) ਵਿੱਚ 3–2 ਦੀ ਵੰਡ ਤੋਂ ਆਏ ਹਨ, ਜਿਸ ਨੇ ਇੱਕ ਸਿਫ਼ਾਰਸ਼ ਦੀ ਬਜਾਏ ਦੋ ਮੁਕਾਬਲੇ ਵਾਲੀਆਂ ਪ੍ਰਸਤਾਵਾਂ ਪੈਦਾ ਕੀਤੀਆਂ। ਬ੍ਰੈਂਡਨ ਲੰਟੀ — ਪ੍ਰੀਮੀਅਰ ਦੁਆਰਾ ਨਿਯੁਕਤ ਇੱਕ MLA — ਦੀ ਪ੍ਰਧਾਨਗੀ ਵਾਲੀ ਇੱਕ ਵੱਖਰੀ MLA ਕਮੇਟੀ ਨਵੰਬਰ 2026 ਦੀ ਆਖਰੀ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ ਇਹਨਾਂ ਵਿਚਕਾਰ ਚੋਣ ਕਰ ਰਹੀ ਹੈ।`},q2:{heading:`ਕੈਨੇਡੀਅਨ ਕਾਨੂੰਨ ਵਿੱਚ "ਗੈਰੀਮੈਂਡਰ" ਦਾ ਕੀ ਅਰਥ ਹੈ?`,body:`ਕੁਝ ਨਹੀਂ। ਕੈਨੇਡੀਅਨ ਪਰੀਖਣ ਵੱਖਰਾ ਹੈ: ਕੀ ਸਰਹੱਦਾਂ ਚਾਰਟਰ ਦੀ ਧਾਰਾ 3 ਦੇ ਅਧੀਨ ਵੋਟਰਾਂ ਨੂੰ <em>ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਪ੍ਰਤੀਨਿਧਤਾ</em> ਦਿੰਦੀਆਂ ਹਨ। ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਇਸ ਪਰੀਖਣ ਅਧੀਨ ਗੰਭੀਰ ਸਵਾਲ ਖੜੇ ਕਰਦੀ ਹੈ; ਸਿਰਫ਼ ਇੱਕ ਜੱਜ ਹੀ ਉਨ੍ਹਾਂ ਦਾ ਨਿਸ਼ਚਿਤ ਜਵਾਬ ਦੇ ਸਕਦਾ ਹੈ, ਅਤੇ ਅਜੇ ਤੱਕ ਕਿਸੇ ਨੇ ਨਹੀਂ ਪੁੱਛਿਆ।`},q3:{heading:`ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਲਈ ਇਸਦਾ ਕੀ ਅਰਥ ਹੈ?`,body:`50/50 ਸੂਬਾਈ ਵੋਟ ਉੱਤੇ, ਆਡਿਟ ਦੇ ਮਾਪ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਨੂੰ ਇੱਕ ਸੰਰਚਨਾਤਮਕ ਸਿਖਰ ਉੱਤੇ ਰੱਖਦੇ ਹਨ — 1.01 ਮਿਲੀਅਨ ਨਿਰਪੱਖ ਤੁਲਨਾਤਮਕ ਨਕਸ਼ਿਆਂ ਵਿੱਚੋਂ 100 ਤੋਂ ਘੱਟ ਉਸੇ ਕਿਸਮ ਦਾ ਸੀਟ ਅਸੰਤੁਲਨ ਪੈਦਾ ਕਰਦੇ ਹਨ। ਉਹ ਅਸੰਤੁਲਨ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ ਕਿਉਂਕਿ 87 ਵਿੱਚੋਂ 58 ਸੀਟਾਂ ਉੱਤੇ — ਦੋ ਤਿਹਾਈ ਸੁਪਰ-ਬਹੁਮਤ — ਸੱਤਾਧਾਰੀ ਪਾਰਟੀ ਅਸਾਧਾਰਨ ਪ੍ਰਕਿਰਿਆਤਮਕ ਸ਼ਕਤੀਆਂ ਖੋਲ੍ਹਦੀ ਹੈ: ਇਹ ਨੋਟਿਸ ਦੀਆਂ ਮਾਨਕ ਮਿਆਦਾਂ ਨੂੰ ਛੱਡ ਸਕਦੀ ਹੈ ਅਤੇ ਜਨਤਕ ਬਿੱਲਾਂ ਨੂੰ ਇੱਕ ਹੀ ਦਿਨ ਵਿੱਚ ਕਈ ਵਿਧਾਨਕ ਪੜਾਵਾਂ ਰਾਹੀਂ ਅੱਗੇ ਧੱਕ ਸਕਦੀ ਹੈ, ਉਨ੍ਹਾਂ ਵਿਚਾਰ-ਵਟਾਂਦਰੇ ਦੀਆਂ ਜਾਂਚਾਂ ਨੂੰ ਟਪਾ ਕੇ ਜੋ ਆਮ ਤੌਰ ਤੇ ਇਸਨੂੰ ਸੀਮਤ ਕਰਦੀਆਂ ਹਨ। ਕੀ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਦਾ ਝੁਕਾਅ 50/50 ਤੋਂ <em>ਇਲਾਵਾ</em> ਹੋਰ ਵੋਟ ਅਨੁਪਾਤਾਂ ਉੱਤੇ ਇੱਕ ਪਾਰਟੀ ਨੂੰ 58-ਸੀਟਾਂ ਦੀ ਹੱਦ ਤੋਂ ਪਾਰ ਧੱਕਣ ਲਈ ਕਾਫ਼ੀ ਵੱਡਾ ਹੈ, ਇਹ ਇੱਕ ਸਵਾਲ ਹੈ ਜਿਸਨੂੰ ਇਹ ਆਡਿਟ ਅਜੇ ਤੱਕ ਨਹੀਂ ਪਰਖ ਸਕਿਆ। ਕੀ ਇਹ ਅਦਲਾ-ਬਦਲੀ ਆਪਣੇ ਆਪ ਵਿੱਚ ਸਵੀਕਾਰਯੋਗ ਹੈ, ਇਹ ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਲਈ ਸਵਾਲ ਹੈ, ਇਸ ਆਡਿਟ ਲਈ ਨਹੀਂ।`},cta_law:`ਕਾਨੂੰਨੀ ਸੰਦਰਭ ਪੜ੍ਹੋ →`,cta_methods:`ਦੇਖੋ ਅਸੀਂ ਕਿਵੇਂ ਪਰਖਿਆ →`},head:{title:`ਅਲਬਰਟਾ ਚੋਣ ਸਰਹੱਦ ਆਡਿਟ`,meta_description:`ਅਲਬਰਟਾ ਦੇ 2026 ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ ਦਾ ਅੰਕੜਾ ਆਡਿਟ — 1,010,000 ਨਿਰਪੱਖ ਨਕਸ਼ੇ, ਅਧਿਕਾਰਤ Elections Alberta ਸ਼ੇਪਫਾਈਲਾਂ, ਪੂਰਵ-ਰਜਿਸਟਰਡ ਪਰੀਖਣ।`},nav:{home_aria:`ਉੱਪਰ ਵਾਪਸ ਜਾਓ`,theme_aria:`ਡਾਰਕ / ਲਾਈਟ ਮੋਡ ਬਦਲੋ`,theme_title:`ਡਾਰਕ ਮੋਡ ਬਦਲੋ`,verdict:`ਫੈਸਲਾ`,why:`ਕਿਉਂ?`,map:`ਨਕਸ਼ਾ`,split:`ਵੰਡ`,litmus:`ਪਰਖ`,crack_pack:`ਫੁੱਟ ਤੇ ਪੈਕ`,for_you:`ਤੁਹਾਡੇ ਲਈ`,impact:`ਅਸਰ`,history:`ਇਤਿਹਾਸ`,canada:`ਕੈਨੇਡਾ`,gerrymanders:`ਗੈਰੀਮੈਂਡਰ`,november:`ਨਵੰਬਰ`,invisible:`ਅਦ੍ਰਿਸ਼`,retractions:`ਵਾਪਸੀਆਂ`,references:`ਹਵਾਲੇ`,resources:`ਸਰੋਤ`},hero:{h1:`ਅਲਬਰਟਾ ਚੋਣ ਸਰਹੱਦ ਆਡਿਟ`,subtitle:`ਅਲਬਰਟਾ ਦੇ ਕਮਿਸ਼ਨ ਨੇ 2026 ਵਿੱਚ ਦੋ ਰਾਈਡਿੰਗ ਨਕਸ਼ੇ ਪੈਦਾ ਕੀਤੇ। ਇਸ ਆਡਿਟ ਨੇ ਉਹਨਾਂ ਦੀ ਤੁਲਨਾ ਕੀਤੀ — ਉਹੀ ਪਰੀਖਣ ਵਰਤਦੇ ਹੋਏ, ਦੋਵਾਂ ਉੱਤੇ ਬਰਾਬਰ ਲਾਗੂ ਕੀਤੇ — ਇਹ ਪੁੱਛਣ ਲਈ ਕਿ ਕੀ ਉਹ ਵੋਟਰਾਂ ਨਾਲ ਇੱਕੋ ਜਿਹਾ ਸਲੂਕ ਕਰਦੇ ਹਨ।`,badge:`ਅਧਿਕਾਰਤ Elections Alberta ਨਕਸ਼ੇ — ਮਈ 2026 ਵਿੱਚ ਪ੍ਰਕਾਸ਼ਿਤ`,cover_note_1:`ਇਹ ਨਕਸ਼ਾ ਅੰਦਰ ਆਉਣ ਦਾ ਸਭ ਤੋਂ ਵਧੀਆ ਰਾਹ ਹੈ। ਜ਼ੂਮ ਕਰਨ ਅਤੇ ਖੋਜਣ ਲਈ ਇਸ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ। ਉੱਪਰਲੇ ਬਟਨ ਘੱਟ-ਗਿਣਤੀ ਦੇ ਨਕਸ਼ੇ, ਬਹੁ-ਗਿਣਤੀ ਦੇ ਨਕਸ਼ੇ, ਅਤੇ 2019 ਵਿੱਚ ਲਾਗੂ ਕੀਤੀਆਂ ਸਰਹੱਦਾਂ ਵਿਚਕਾਰ ਬਦਲਦੇ ਹਨ — ਜਾਂ ਤਿੰਨੋਂ ਨੂੰ ਲੇਅਰ ਕਰੋ ਇਹ ਦੇਖਣ ਲਈ ਕਿ ਉਹ ਕਿੱਥੇ ਠੀਕ ਨਾਲ ਵੱਖ ਹੁੰਦੇ ਹਨ। <strong>Detail</strong> ਹਰ ਪੋਲਿੰਗ ਖੇਤਰ ਨੂੰ 2023 ਵਿੱਚ ਲੋਕਾਂ ਦੇ ਵੋਟਾਂ ਮੁਤਾਬਕ ਰੰਗਦਾ ਹੈ; <strong>Trend</strong> ਜ਼ਿਲ੍ਹੇ ਅਨੁਸਾਰ ਪਾਰਟੀ ਛਾਂ ਜੋੜਦਾ ਹੈ (ਨੀਲਾ UCP, ਸੰਤਰੀ NDP); <strong>Lines</strong> ਸਰਹੱਦਾਂ ਨੂੰ ਚਾਲੂ-ਬੰਦ ਕਰਦਾ ਹੈ। <strong>Find</strong> ਨਾਮ ਅਨੁਸਾਰ ਕਿਸੇ ਵੀ ਰਾਈਡਿੰਗ ਉੱਤੇ ਪਹੁੰਚਦਾ ਹੈ।`,cover_note_2:`ਵਿਊਪੋਰਟ ਨੂੰ ਲਾਕ ਕਰਕੇ ਨਕਸ਼ਿਆਂ ਵਿਚਕਾਰ ਬਦਲਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੋ — ਦੇਖੋ ਕਿਵੇਂ ਸਰਹੱਦ ਖਿਸਕਦੀ ਹੈ ਜਦੋਂ ਕਿ ਹੇਠਾਂ ਦੇ ਵੋਟਰ ਉੱਥੇ ਹੀ ਰਹਿੰਦੇ ਹਨ। ਇਹ ਇੱਕ ਇਸ਼ਾਰੇ ਵਿੱਚ ਸਾਰਾ ਸਵਾਲ ਹੈ।`,cover_note_3:`ਜਦੋਂ ਤੁਹਾਡੀ ਖੋਜ ਮੁਕੰਮਲ ਹੋ ਜਾਵੇ, ਸੰਖੇਪ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ। ਪੂਰੇ ਤਕਨੀਕੀ ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਸਰੋਤ ਸੈਕਸ਼ਨ ਦੇਖੋ। ਸਾਰਾ ਡੇਟਾ ਅਧਿਕਾਰਤ Elections Alberta ਸ਼ੇਪਫਾਈਲਾਂ ਅਤੇ ਹੋਰ ਸਰਕਾਰੀ ਅਤੇ ਓਪਨ-ਸੋਰਸ ਰਿਕਾਰਡਾਂ ਤੋਂ ਹੈ।`,image_alt:`ਅਲਬਰਟਾ ਦੇ ਚੋਣ ਜ਼ਿਲ੍ਹਾ ਨਕਸ਼ੇ — ਕਮਿਸ਼ਨ ਦੀ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ, 2023 ਦੇ ਵੋਟਾਂ ਮੁਤਾਬਕ ਰੰਗੀ`,map_hint:`ਇੰਟਰਐਕਟਿਵ ਤੌਰ ਤੇ ਖੋਜਣ ਲਈ ਕਲਿੱਕ ਕਰੋ`,btn_title:`ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ਾ ਖੋਲ੍ਹਣ ਲਈ ਕਲਿੱਕ ਕਰੋ`,btn_aria:`ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ਾ ਖੋਲ੍ਹੋ`},section1:{heading:`ਮੁੜ-ਜ਼ਿਲ੍ਹਾਬੰਦੀ ਕੀ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਇਸ ਦੀ ਪਰਵਾਹ ਕਿਉਂ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ?`,p1:`ਅਲਬਰਟਾ ਦਾ ਹਰ ਵੋਟਰ ਇੱਕ <em>ਚੋਣ ਜ਼ਿਲ੍ਹੇ</em> ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ — ਸੂਬੇ ਦਾ ਇੱਕ ਹਿੱਸਾ ਜੋ ਵਿਧਾਨ ਸਭਾ ਲਈ ਇੱਕ ਵਿਅਕਤੀ ਨੂੰ ਚੁਣਦਾ ਹੈ। 87 ਜ਼ਿਲ੍ਹੇ ਹਨ। ਹਰ ਜ਼ਿਲ੍ਹਾ ਇੱਕ MLA ਚੁਣਦਾ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਸੂਬਾਈ ਚੋਣ ਵਿੱਚ ਵੋਟ ਪਾਉਂਦੇ ਹੋ, ਤੁਸੀਂ ਉਸ ਜ਼ਿਲ੍ਹੇ ਲਈ MLA ਚੁਣ ਰਹੇ ਹੋ ਜਿਸ ਵਿੱਚ ਤੁਸੀਂ ਰਹਿੰਦੇ ਹੋ। ਜ਼ਿਆਦਾਤਰ ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਦਾ ਵਿਧਾਨ ਸਭਾ ਨਾਲ ਪੂਰਾ ਸੰਪਰਕ ਇਹੀ ਹੈ: ਇੱਕ MLA, ਇੱਕ ਜ਼ਿਲ੍ਹਾ, ਇੱਕ ਵੋਟ।`,p2:`ਇਹ ਜ਼ਿਲ੍ਹੇ ਦੀਆਂ ਲਾਈਨਾਂ ਸਥਾਈ ਨਹੀਂ ਹਨ। ਲੋਕ ਚਲੇ ਜਾਂਦੇ ਹਨ, ਮੁਹੱਲੇ ਵੱਡੇ ਹੁੰਦੇ ਹਨ, ਪੇਂਡੂ ਖੇਤਰ ਖਾਲੀ ਹੁੰਦੇ ਹਨ, ਸ਼ਹਿਰ ਫੈਲਦੇ ਹਨ। ਹਰ ਅੱਠ ਤੋਂ ਦਸ ਸਾਲਾਂ ਬਾਅਦ, ਅਲਬਰਟਾ ਨੂੰ ਲਾਈਨਾਂ ਨੂੰ ਮੁੜ ਖਿੱਚਣਾ ਚਾਹੀਦਾ ਹੈ ਤਾਂ ਜੋ ਹਰ ਜ਼ਿਲ੍ਹਾ ਲਗਭਗ ਸਹੀ ਆਕਾਰ ਦਾ ਹੋਵੇ ਅਤੇ ਇਹ ਪ੍ਰਤੀਬਿੰਬਤ ਕਰੇ ਕਿ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਅਸਲ ਵਿੱਚ ਹੁਣ ਕਿਵੇਂ ਰਹਿੰਦੇ ਹਨ। ਮੁੜ-ਖਿੱਚਣ ਵਾਲੀ ਸੰਸਥਾ <em>ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ</em> ਹੈ — ਜੱਜਾਂ, ਵਕੀਲਾਂ, ਅਤੇ ਜਨਤਕ ਮੈਂਬਰਾਂ ਦਾ ਇੱਕ ਸੁਤੰਤਰ ਕਮਿਸ਼ਨ, ਨਾ ਕਿ ਸਿਆਸਤਦਾਨਾਂ ਦਾ।`,p3:`ਇਹੀ ਸਟੈਂਡਰਡ ਪ੍ਰਕਿਰਿਆ ਹੈ। ਇਸ ਵਾਰ, ਸਟੈਂਡਰਡ ਪ੍ਰਕਿਰਿਆ ਨੇ ਕੁਝ ਅਸਾਧਾਰਨ ਪੈਦਾ ਕੀਤਾ। ਕਮਿਸ਼ਨ ਦੇ ਪੰਜ ਮੈਂਬਰ 3 ਬਨਾਮ 2 ਵਿੱਚ ਵੰਡੇ ਗਏ ਕਿ ਨਕਸ਼ੇ ਨੂੰ ਕਿਹੋ ਜਿਹਾ ਦਿਖਣਾ ਚਾਹੀਦਾ ਹੈ, ਅਤੇ ਇੱਕ ਸਿਫ਼ਾਰਸ਼ ਉੱਤੇ ਸਹਿਮਤ ਹੋਣ ਦੀ ਬਜਾਏ ਉਹਨਾਂ ਨੇ ਦੋ ਤਿਆਰ ਕੀਤੀਆਂ: ਇੱਕ <em>ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> (ਤਿੰਨ ਕਮਿਸ਼ਨਰਾਂ ਦੁਆਰਾ ਸਮਰਥਨ) ਅਤੇ ਇੱਕ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> (ਦੋਆਂ ਦੁਆਰਾ ਸਮਰਥਨ)। ਦੋਵੇਂ ਮੇਜ਼ ਉੱਤੇ ਹਨ। ਬ੍ਰੈਂਡਨ ਲੰਟੀ ਦੀ ਅਗਵਾਈ ਵਾਲੀ MLA ਦੀ ਇੱਕ ਵੱਖਰੀ ਕਮੇਟੀ — ਜਿਸਨੂੰ ਪ੍ਰੀਮੀਅਰ ਨੇ ਇਸ ਖਾਸ ਫੈਸਲੇ ਲਈ ਨਿਯੁਕਤ ਕੀਤਾ — ਉਨ੍ਹਾਂ ਵਿਚਕਾਰ ਚੋਣ ਕਰ ਰਹੀ ਹੈ। ਨਵੰਬਰ 2026 ਤੋਂ ਪਹਿਲਾਂ ਵਿਧਾਨ ਸਭਾ ਨੂੰ ਉਸ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇਣੀ ਚਾਹੀਦੀ ਹੈ ਜੋ ਉਸ ਕਮੇਟੀ ਤੋਂ ਬਚ ਜਾਂਦੀ ਹੈ।`,p4:`ਇਹ ਤੁਹਾਡੇ ਲਈ ਕਿਉਂ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ: ਲਾਈਨਾਂ ਫੈਸਲਾ ਕਰਦੀਆਂ ਹਨ ਕਿ ਤੁਹਾਡਾ MLA ਕੌਣ ਹੈ। ਉਹ ਫੈਸਲਾ ਕਰਦੀਆਂ ਹਨ ਕਿ ਕਿਹੜੇ ਮੁਹੱਲੇ, ਕਸਬੇ, ਅਤੇ ਚਿੰਤਾਵਾਂ ਇਕੱਠੇ ਪ੍ਰਤੀਨਿਧਤਾ ਪ੍ਰਾਪਤ ਕਰਦੀਆਂ ਹਨ। ਜੇ ਤੁਹਾਡਾ ਸ਼ਹਿਰ ਇੱਕ ਦੀ ਥਾਂ ਚਾਰ MLAs ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਕੋਈ ਇੱਕ ਨੁਮਾਇੰਦਾ ਪੂਰੇ ਸ਼ਹਿਰ ਲਈ ਜਵਾਬਦੇਹ ਨਹੀਂ ਹੈ। ਜੇ ਤੁਹਾਡਾ ਹਿੱਤ ਸਮੁਦਾਇ — ਇੱਕ ਛੋਟਾ ਕਸਬਾ, ਇੱਕ ਪੇਂਡੂ ਖੇਤਰ, ਇੱਕ ਡਾਊਨਟਾਊਨ ਕੋਰ — ਜ਼ਿਲ੍ਹਿਆਂ ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ, ਸੂਬਾਈ ਫੈਸਲਿਆਂ ਉੱਤੇ ਤੁਹਾਡੀ ਆਵਾਜ਼ ਪਤਲੀ ਹੁੰਦੀ ਹੈ। ਨਕਸ਼ਾ ਇਹ ਵੀ ਆਕਾਰ ਦਿੰਦਾ ਹੈ ਕਿ ਕਿਹੜੀ ਪਾਰਟੀ ਸਰਕਾਰ ਬਣਾ ਸਕਦੀ ਹੈ, ਅਤੇ ਕਿਸ ਮਾਰਜਨ ਨਾਲ। ਆਡਿਟ ਦੀ ਖਾਸ ਖੋਜ (ਕਿ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਇੱਕ ਸੰਰਚਨਾਤਮਕ ਸਿਖਰ ਉੱਤੇ ਬੈਠੀ ਹੈ) ਉਹ ਕਾਰਨ ਹੈ ਜੋ ਤੁਸੀਂ ਇਸ ਸਾਈਟ ਨੂੰ ਪੜ੍ਹ ਰਹੇ ਹੋ, ਪਰ ਵਿਆਪਕ ਸਵਾਲ ਪੁਰਾਣਾ ਹੈ ਅਤੇ ਹਰ ਮੁੜ-ਜ਼ਿਲ੍ਹਾਬੰਦੀ ਚੱਕਰ ਉੱਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ: ਕੀ ਲਾਈਨਾਂ ਇਹ ਪ੍ਰਤੀਬਿੰਬਤ ਕਰਦੀਆਂ ਹਨ ਕਿ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਕਿਵੇਂ ਰਹਿੰਦੇ ਹਨ, ਜਾਂ ਉਹ ਉਸ ਰਾਜਨੀਤੀ ਨੂੰ ਆਕਾਰ ਦਿੰਦੀਆਂ ਹਨ ਜੋ ਬਾਅਦ ਵਿੱਚ ਆਉਂਦੀ ਹੈ?`,p5:`ਇਸ ਪੰਨੇ ਦਾ ਬਾਕੀ ਹਿੱਸਾ ਇਸ ਦੇ ਪਾਰ ਚੱਲਦਾ ਹੈ ਕਿ ਦੋ ਪ੍ਰਸਤਾਵਿਤ ਨਕਸ਼ੇ ਅਸਲ ਵਿੱਚ ਕੀ ਕਰਦੇ ਹਨ।`,key_terms_lead:`ਇਸ ਸੈਕਸ਼ਨ ਦੇ ਮੁੱਖ ਸ਼ਬਦ — ਪੜ੍ਹਨ ਲਈ ਕਲਿੱਕ ਕਰੋ:`},boundary:{heading:`ਇਹ ਆਡਿਟ ਤੁਹਾਨੂੰ ਕੀ ਦੱਸ ਸਕਦਾ ਹੈ ਅਤੇ ਕੀ ਨਹੀਂ`,can_1:`1.45 ਕਰੋੜ ਬੇਤਰਤੀਬੀ ਤੁਲਨਾਤਮਕ ਨਕਸ਼ਿਆਂ ਵਿੱਚੋਂ 1 ਤੋਂ ਘੱਟ ਨੇ ਚਾਰੇ ਅੰਕੜਾ ਮਾਪਾਂ ਨੂੰ ਮਿਲਾ ਕੇ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਜਿੰਨੇ ਅਤਿਅੰਤ ਨਮੂਨੇ ਪੈਦਾ ਕੀਤੇ।`,can_2:`ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ 5 ਵਿੱਚੋਂ 5 ਪੂਰਵ-ਰਜਿਸਟਰਡ ਸੰਰਚਨਾਤਮਕ ਪਰੀਖਣਾਂ ਵਿੱਚ ਅਸਫ਼ਲ ਰਹਿੰਦੀ ਹੈ। ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ 5 ਵਿੱਚੋਂ 0 ਵਿੱਚ ਅਸਫ਼ਲ ਰਹਿੰਦੀ ਹੈ।`,can_3:`ਇਹ ਨਤੀਜੇ ਉਹਨਾਂ ਨਕਸ਼ਿਆਂ ਨਾਲ ਮੇਲ ਖਾਂਦੇ ਹਨ ਜੋ ਮਜ਼ਬੂਤ ਪਾਰਟੀ ਪ੍ਰਭਾਵ ਪੈਦਾ ਕਰਦੇ ਹਨ, ਅਤੇ ਬੇਤਰਤੀਬੀ ਤੁਲਨਾਤਮਕ ਸੈੱਟ ਦੇ ਉਤਪਾਦਨ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ।`,cant_1:`ਆਡਿਟ ਇਹ ਸਥਾਪਤ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਕਿਸੇ ਕਮਿਸ਼ਨਰ ਨੇ ਉਹਨਾਂ ਪਾਰਟੀ ਪ੍ਰਭਾਵਾਂ ਦੀ ਨੀਅਤ ਰੱਖੀ ਜੋ ਇਹ ਮਾਪਦਾ ਹੈ। ਸਰਹੱਦੀ ਜਿਓਮੈਟਰੀ ਨੀਅਤ ਨੂੰ ਪ੍ਰਗਟ ਨਹੀਂ ਕਰ ਸਕਦੀ।`,cant_2:`ਆਡਿਟ ਇਹ ਭਵਿੱਖਬਾਣੀ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਲੰਟੀ ਕਮੇਟੀ ਕੀ ਚੁਣੇਗੀ, ਨਵੰਬਰ 2026 ਦੀ ਵੋਟ ਕੀ ਹੋਵੇਗੀ, ਜਾਂ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਕਿਵੇਂ ਪ੍ਰਤੀਕਿਰਿਆ ਕਰਨਗੇ।`,cant_3:`ਆਡਿਟ ਇਹ ਭਵਿੱਖਬਾਣੀ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਜੇ ਕਿਸੇ ਪ੍ਰਸਤਾਵ ਖਿਲਾਫ਼ ਚਾਰਟਰ ਚੁਣੌਤੀ ਦਾਇਰ ਕੀਤੀ ਜਾਂਦੀ ਤਾਂ ਅਦਾਲਤ ਕਿਵੇਂ ਫੈਸਲਾ ਕਰੇਗੀ।`,cant_4:`ਆਡਿਟ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀਗਤ ਵੋਟਰ ਨੂੰ ਇਹ <strong>ਨਹੀਂ</strong> ਦੱਸਦਾ ਕਿ ਕੀ ਪੋਜੀਸ਼ਨ ਲਵੇ ਜਾਂ ਇਸ ਜਾਣਕਾਰੀ ਨਾਲ ਕੀ ਕਰੇ। ਇਹ ਫੈਸਲਾ ਤੁਹਾਡਾ ਹੈ।`}},"zh-Hans":{selector:{label:`选择语言`},disclaimer:{text:`本网站由 AI 翻译。在翻译进行期间,部分内容可能仍以英文显示。如果您发现错误或希望帮助翻译本项目,请%s。`,link_label:`联系我们`},opener:{heading:`这是为谁准备的?`,body:`为我们。为我们所有人。无论你是乡村居民、城市居民、好奇者、政治爱好者、记者、律师、学者还是政治人物——我们所有人。因为这影响着我们所有人。无论你是否喜欢执政党,分裂的委员会所产生的结果是前所未有的。它给了我们一个前所未有的机会,得以窥视这台机器的内部运作。现在我们可以建立一个基准——一系列测试,之后的一切都可以以此为标准进行评估。让我向你展示我所发现的。`},verdict:{q1:{heading:`所提议的地图是否构成选区不公?`,body:`"Gerrymander"(选区不公划分)并非加拿大法院使用的术语。但如果以普通人理解的日常意义来衡量——本次审计的证据合理地支持将<em>少数派提议</em>(若被采纳)称为一份严重经过党派划分的地图。本次审计运行的每一项结构性测试都标记了<em>少数派提议</em>;没有任何一项测试标记了另一份提议(<em>多数派提议</em>)。`,footnote:`"多数派"和"少数派"的称谓源自选举边界委员会(由 Miller 法官主持)内部 3 比 2 的分裂——该委员会未能形成单一建议,而是提出了两份相互竞争的提议。一个由 Brandon Lunty(由省长任命的 MLA)主持的独立 MLA 委员会正在于 2026 年 11 月截止日期前在两者之间作出选择。`},q2:{heading:`"Gerrymander" 在加拿大法律中是什么意思?`,body:`没有意义。加拿大的检验标准不同:即边界是否在《宪章》第3条之下给予选民<em>有效代表权</em>。少数派提议在该标准下提出了严重问题;只有法官才能给出确定性的回答,而目前尚无人提起诉讼。`},q3:{heading:`这对阿尔伯塔人意味着什么?`,body:`在50/50的省级投票情况下,审计的测量将少数派提议置于结构性极端——在101万张中立比较地图中,产生类似议席不平衡的不到100张。这种不平衡之所以重要,是因为在87席中获得58席——即三分之二的超级多数——执政党便解锁了非常规的程序权力:它可以免除标准通知期,并在一天内将公共法案推过多个立法阶段,绕过通常约束它的审议性检查。少数派提议的倾斜是否大到足以在<em>非</em>50/50的投票比例下将一个政党推过58席门槛,这是本次审计尚未测试的问题。这种取舍本身是否可接受,这是属于阿尔伯塔人的问题,而非本次审计的问题。`},cta_law:`阅读法律背景 →`,cta_methods:`查看我们如何测试 →`},head:{title:`阿尔伯塔选举边界审计`,meta_description:`对阿尔伯塔2026年选举边界委员会的统计审计——101万张中立地图、Elections Alberta官方shapefile、预先注册的测试。`},nav:{home_aria:`返回顶部`,theme_aria:`切换深色 / 浅色模式`,theme_title:`切换深色模式`,verdict:`结论`,why:`为什么?`,map:`地图`,split:`分裂`,litmus:`试金石`,crack_pack:`分散与集中`,for_you:`对你而言`,impact:`影响`,history:`历史`,canada:`加拿大`,gerrymanders:`选区操控`,november:`十一月`,invisible:`隐形`,retractions:`撤回`,references:`参考资料`,resources:`资源`},hero:{h1:`阿尔伯塔选举边界审计`,subtitle:`阿尔伯塔的委员会在2026年提出了两份选区地图。本次审计对它们进行了比较——使用相同的测试,平等地应用于两者——以询问它们是否以同样的方式对待选民。`,badge:`Elections Alberta 官方地图——2026年5月发布`,cover_note_1:`这张地图是最好的入口。点击它即可缩放和探索。顶部按钮可在少数派地图、多数派地图和2019年颁布的边界之间切换——或叠加三者以查看它们的分歧之处。<strong>Detail</strong> 根据2023年人们的投票情况为每个投票区上色;<strong>Trend</strong> 按选区添加党派色调(蓝色UCP,橙色NDP);<strong>Lines</strong> 切换边界的开关。<strong>Find</strong> 按名称跳转到任何选区。`,cover_note_2:`尝试锁定视图并在地图之间切换——观察一条边界在下方选民保持不动时如何移动。这就是整个问题,用一个动作表达。`,cover_note_3:`当您探索完毕后,向下滚动查看摘要。如需完整的技术分析,请参阅"资源"部分。所有数据均来自 Elections Alberta 官方shapefile以及其他政府和开源记录。`,image_alt:`阿尔伯塔选区地图——委员会少数派提议,按2023年投票上色`,map_hint:`点击进行交互式探索`,btn_title:`点击打开交互式地图`,btn_aria:`打开交互式地图`},section1:{heading:`什么是选区划分,以及为什么你应该关心?`,p1:`阿尔伯塔的每位选民都生活在一个<em>选区</em>中——省份的一个切片,负责选出一位省议会议员。共有87个选区。每个选区选出一位MLA。当你在省级选举中投票时,你是在为你所居住的选区选出MLA。这就是大多数阿尔伯塔人与立法机构的全部联系:一位MLA,一个选区,一票。`,p2:`这些选区界线并非永久。人会搬家,社区会扩大,乡村会变少,城市会扩张。每隔八到十年,阿尔伯塔应该重新划界,使每个选区大致大小合适,并反映阿尔伯塔人现在实际的居住情况。负责重新划界的机构是<em>选举边界委员会</em>——一个由法官、律师和公众成员组成的独立委员会,而非政客。`,p3:`那是标准程序。这一次,标准程序产生了不寻常的结果。委员会的五名成员就地图应是什么样子分裂成了3比2,与其达成一项建议,他们提出了两份:一份<em>多数派提议</em>(由三位委员支持)和一份<em>少数派提议</em>(由两位支持)。两份都摆在桌上。一个由Brandon Lunty主持的独立MLA委员会——由省长为此特定决定任命——正在两者之间作出选择。立法机构必须在2026年11月之前批准在该委员会中存活下来的那一份。`,p4:`为什么这对你重要:这些界线决定了谁是你的MLA。它们决定了哪些社区、城镇和关切被一起代表。如果你的城市被切分到四位MLA而不是一位,没有任何一位代表对整个城市负责。如果你的利益共同体——一个小镇、一个乡村地区、一个市中心——被划分到不同的选区,你在省级决策中的声音被稀释。这张地图还塑造了哪个政党能组建政府,以及以何种边际。本次审计的具体发现(少数派提议处于结构性极端)是你正在阅读本网站的原因,但更广泛的问题更古老,适用于每一个选区重划周期:这些界线反映了阿尔伯塔人的实际居住方式,还是塑造了之后的政治?`,p5:`本页的其余部分将讲解这两份提议地图实际上做了什么。`,key_terms_lead:`本节关键术语 — 点击阅读:`},boundary:{heading:`本次审计能告诉你什么,不能告诉你什么`,can_1:`在1450万张随机生成的比较地图中,少数派提议在所有四项统计指标综合方面所产生的极端模式不到1张。`,can_2:`少数派提议在5项预先注册的结构性测试中全部失败。多数派提议在5项中失败0项。`,can_3:`这些结果与产生强烈党派效应的地图一致,与随机比较集所产生的结果不一致。`,cant_1:`本次审计<strong>未能</strong>证明任何委员有意制造其所测量的党派效应。边界几何无法揭示意图。`,cant_2:`本次审计<strong>不</strong>预测 Lunty 委员会会做出什么选择,2026 年 11 月投票结果如何,或阿尔伯塔人会如何反应。`,cant_3:`本次审计<strong>不</strong>预测如果对任一提议提起《宪章》诉讼,法院将如何裁决。`,cant_4:`本次审计<strong>不</strong>告诉任何选民应采取什么立场或如何处理这些信息。这是由你决定的。`}},"zh-Hant":{selector:{label:`選擇語言`},disclaimer:{text:`本網站由 AI 翻譯。在翻譯進行期間,部分內容可能仍以英文顯示。如果您發現錯誤或希望幫助翻譯本項目,請%s。`,link_label:`聯絡我們`},opener:{heading:`這是為誰準備的?`,body:`為我們。為我們所有人。無論你是鄉村居民、城市居民、好奇者、政治愛好者、記者、律師、學者還是政治人物——我們所有人。因為這影響著我們所有人。無論你是否喜歡執政黨,分裂的委員會所產生的結果是前所未有的。它給了我們一個前所未有的機會,得以窺視這台機器的內部運作。現在我們可以建立一個基準——一系列測試,之後的一切都可以以此為標準進行評估。讓我向你展示我所發現的。`},verdict:{q1:{heading:`所提議的地圖是否構成選區不公?`,body:`「Gerrymander」(選區不公劃分)並非加拿大法院使用的術語。但如果以普通人理解的日常意義來衡量——本次審計的證據合理地支持將<em>少數派提議</em>(若被採納)稱為一份嚴重經過黨派劃分的地圖。本次審計運行的每一項結構性測試都標記了<em>少數派提議</em>;沒有任何一項測試標記了另一份提議(<em>多數派提議</em>)。`,footnote:`「多數派」和「少數派」的稱謂源自選舉邊界委員會(由 Miller 法官主持)內部 3 比 2 的分裂——該委員會未能形成單一建議,而是提出了兩份相互競爭的提議。一個由 Brandon Lunty(由省長任命的 MLA)主持的獨立 MLA 委員會正在於 2026 年 11 月截止日期前在兩者之間作出選擇。`},q2:{heading:`「Gerrymander」在加拿大法律中是什麼意思?`,body:`沒有意義。加拿大的檢驗標準不同:即邊界是否在《憲章》第3條之下給予選民<em>有效代表權</em>。少數派提議在該標準下提出了嚴重問題;只有法官才能給出確定性的回答,而目前尚無人提起訴訟。`},q3:{heading:`這對阿爾伯塔人意味著什麼?`,body:`在50/50的省級投票情況下,審計的測量將少數派提議置於結構性極端——在101萬張中立比較地圖中,產生類似議席不平衡的不到100張。這種不平衡之所以重要,是因為在87席中獲得58席——即三分之二的超級多數——執政黨便解鎖了非常規的程序權力:它可以免除標準通知期,並在一天內將公共法案推過多個立法階段,繞過通常約束它的審議性檢查。少數派提議的傾斜是否大到足以在<em>非</em>50/50的投票比例下將一個政黨推過58席門檻,這是本次審計尚未測試的問題。這種取捨本身是否可接受,這是屬於阿爾伯塔人的問題,而非本次審計的問題。`},cta_law:`閱讀法律背景 →`,cta_methods:`查看我們如何測試 →`},head:{title:`阿爾伯塔選舉邊界審計`,meta_description:`對阿爾伯塔2026年選舉邊界委員會的統計審計——101萬張中立地圖、Elections Alberta官方shapefile、預先註冊的測試。`},nav:{home_aria:`返回頂部`,theme_aria:`切換深色 / 淺色模式`,theme_title:`切換深色模式`,verdict:`結論`,why:`為什麼?`,map:`地圖`,split:`分裂`,litmus:`試金石`,crack_pack:`分散與集中`,for_you:`對你而言`,impact:`影響`,history:`歷史`,canada:`加拿大`,gerrymanders:`選區操控`,november:`十一月`,invisible:`隱形`,retractions:`撤回`,references:`參考資料`,resources:`資源`},hero:{h1:`阿爾伯塔選舉邊界審計`,subtitle:`阿爾伯塔的委員會在2026年提出了兩份選區地圖。本次審計對它們進行了比較——使用相同的測試,平等地應用於兩者——以詢問它們是否以同樣的方式對待選民。`,badge:`Elections Alberta 官方地圖——2026年5月發佈`,cover_note_1:`這張地圖是最好的入口。點擊它即可縮放和探索。頂部按鈕可在少數派地圖、多數派地圖和2019年頒布的邊界之間切換——或疊加三者以查看它們的分歧之處。<strong>Detail</strong> 根據2023年人們的投票情況為每個投票區上色;<strong>Trend</strong> 按選區添加黨派色調(藍色UCP,橙色NDP);<strong>Lines</strong> 切換邊界的開關。<strong>Find</strong> 按名稱跳轉到任何選區。`,cover_note_2:`嘗試鎖定視圖並在地圖之間切換——觀察一條邊界在下方選民保持不動時如何移動。這就是整個問題,用一個動作表達。`,cover_note_3:`當您探索完畢後,向下滾動查看摘要。如需完整的技術分析,請參閱「資源」部分。所有數據均來自 Elections Alberta 官方shapefile以及其他政府和開源記錄。`,image_alt:`阿爾伯塔選區地圖——委員會少數派提議,按2023年投票上色`,map_hint:`點擊進行互動式探索`,btn_title:`點擊打開互動式地圖`,btn_aria:`打開互動式地圖`},section1:{heading:`什麼是選區劃分,以及為什麼你應該關心?`,p1:`阿爾伯塔的每位選民都生活在一個<em>選區</em>中——省份的一個切片,負責選出一位省議會議員。共有87個選區。每個選區選出一位MLA。當你在省級選舉中投票時,你是在為你所居住的選區選出MLA。這就是大多數阿爾伯塔人與立法機構的全部聯繫:一位MLA,一個選區,一票。`,p2:`這些選區界線並非永久。人會搬家,社區會擴大,鄉村會變少,城市會擴張。每隔八到十年,阿爾伯塔應該重新劃界,使每個選區大致大小合適,並反映阿爾伯塔人現在實際的居住情況。負責重新劃界的機構是<em>選舉邊界委員會</em>——一個由法官、律師和公眾成員組成的獨立委員會,而非政客。`,p3:`那是標準程序。這一次,標準程序產生了不尋常的結果。委員會的五名成員就地圖應是什麼樣子分裂成了3比2,與其達成一項建議,他們提出了兩份:一份<em>多數派提議</em>(由三位委員支持)和一份<em>少數派提議</em>(由兩位支持)。兩份都擺在桌上。一個由Brandon Lunty主持的獨立MLA委員會——由省長為此特定決定任命——正在兩者之間作出選擇。立法機構必須在2026年11月之前批准在該委員會中存活下來的那一份。`,p4:`為什麼這對你重要:這些界線決定了誰是你的MLA。它們決定了哪些社區、城鎮和關切被一起代表。如果你的城市被切分到四位MLA而不是一位,沒有任何一位代表對整個城市負責。如果你的利益共同體——一個小鎮、一個鄉村地區、一個市中心——被劃分到不同的選區,你在省級決策中的聲音被稀釋。這張地圖還塑造了哪個政黨能組建政府,以及以何種邊際。本次審計的具體發現(少數派提議處於結構性極端)是你正在閱讀本網站的原因,但更廣泛的問題更古老,適用於每一個選區重劃週期:這些界線反映了阿爾伯塔人的實際居住方式,還是塑造了之後的政治?`,p5:`本頁的其餘部分將講解這兩份提議地圖實際上做了什麼。`,key_terms_lead:`本節關鍵術語 — 點擊閱讀:`},boundary:{heading:`本次審計能告訴你什麼,不能告訴你什麼`,can_1:`在1450萬張隨機生成的比較地圖中,少數派提議在所有四項統計指標綜合方面所產生的極端模式不到1張。`,can_2:`少數派提議在5項預先註冊的結構性測試中全部失敗。多數派提議在5項中失敗0項。`,can_3:`這些結果與產生強烈黨派效應的地圖一致,與隨機比較集所產生的結果不一致。`,cant_1:`本次審計<strong>未能</strong>證明任何委員有意製造其所測量的黨派效應。邊界幾何無法揭示意圖。`,cant_2:`本次審計<strong>不</strong>預測 Lunty 委員會會做出什麼選擇,2026 年 11 月投票結果如何,或阿爾伯塔人會如何反應。`,cant_3:`本次審計<strong>不</strong>預測如果對任一提議提起《憲章》訴訟,法院將如何裁決。`,cant_4:`本次審計<strong>不</strong>告訴任何選民應採取什麼立場或如何處理這些信息。這是由你決定的。`}}};function m(e,t){let n=e;for(let e of t.split(`.`))if(n&&typeof n==`object`&&e in n)n=n[e];else return;return n}function h(e,t){let n=m(p[e],t);if(typeof n==`string`)return n;let r=m(p.en,t);return typeof r==`string`?r:`[missing:${t}]`}export{d as a,f as i,i as n,r,h as t};